        ? { emailVerificationCode: code, emailVerificationExpiry: expiry }
        : { phoneVerificationCode: code, phoneVerificationExpiry: expiry };

      await storage.updateUser(userId, updateData);

      // In a real implementation, send email/SMS here
      const contactInfo = type === 'email' ? user.email : user.phone;
      console.log(`Verification code for ${contactInfo}: ${code}`);

      // For demo purposes, always succeed
      res.json({ 
        message: `Verification code sent to ${contactInfo}`,
        // In development, return code for testing
        ...(process.env.NODE_ENV === 'development' && { code })
      });
    } catch (error) {
      console.error("Error sending verification code:", error);
      res.status(500).json({ error: "Failed to send verification code" });
    }
  });

  app.post("/api/verification/verify-code", async (req, res) => {
    try {
      const { type, code, userId } = req.body;

      if (!type || !code || !userId || !['email', 'phone'].includes(type)) {
        return res.status(400).json({ error: "Invalid verification data" });
      }

      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const storedCode = type === 'email' ? user.emailVerificationCode : user.phoneVerificationCode;
      const expiry = type === 'email' ? user.emailVerificationExpiry : user.phoneVerificationExpiry;

      if (!storedCode || !expiry) {
        return res.status(400).json({ error: "No verification code found" });
      }

      if (new Date() > expiry) {
        return res.status(400).json({ error: "Verification code expired" });
      }

      if (storedCode !== code) {
        return res.status(400).json({ error: "Invalid verification code" });
      }

      // Mark as verified and clear verification data
      const updateData = type === 'email' 
        ? { 
            emailVerified: true, 
            emailVerificationCode: null, 
            emailVerificationExpiry: null,
            verificationScore: user.phoneVerified ? 50 : 25
          }
        : { 
            phoneVerified: true, 
            phoneVerificationCode: null, 
            phoneVerificationExpiry: null,
            verificationScore: user.emailVerified ? 50 : 25
          };

      // Update overall verification status
      if ((type === 'email' && user.phoneVerified) || (type === 'phone' && user.emailVerified)) {
        updateData.verificationScore = user.documentVerified ? 100 : 50;
      }

      if (updateData.verificationScore && updateData.verificationScore >= 50) {
        (updateData as any).isVerified = true;
      }

      const updatedUser = await storage.updateUser(userId, updateData);

      res.json({ 
        message: `${type} verification successful`,
        verified: true,
        verificationScore: updateData.verificationScore
      });
    } catch (error) {
      console.error("Error verifying code:", error);
      res.status(500).json({ error: "Failed to verify code" });
    }
  });

  app.post("/api/verification/upload-document", async (req, res) => {
    try {
      // For this demo, we'll simulate document upload
      const { documentType, userId } = req.body;

      if (!documentType || !userId || !['cin', 'passport'].includes(documentType)) {
        return res.status(400).json({ error: "Invalid document type or user ID" });
      }

      const user = await storage.getUser(parseInt(userId));
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      // Simulate document upload URLs
      const frontUrl = `/uploads/documents/${userId}_${documentType}_front_${Date.now()}.jpg`;
      const backUrl = documentType === 'cin' ? `/uploads/documents/${userId}_${documentType}_back_${Date.now()}.jpg` : null;

      // Update user with document info (simulating verification success)
      const updateData = {
        documentType,
        documentFrontUrl: frontUrl,
        documentBackUrl: backUrl,
        documentVerified: true, // In real implementation, this would be manual verification
        documentVerifiedAt: new Date(),
        verificationScore: (user.emailVerified ? 25 : 0) + (user.phoneVerified ? 25 : 0) + 50,
        isVerified: true // Full verification achieved
      };

      const updatedUser = await storage.updateUser(parseInt(userId), updateData);

      res.json({ 
        message: "Document uploaded successfully and verified",
        documentType,
        frontUrl,
        backUrl,
        verified: true,
        verificationScore: updateData.verificationScore
      });
    } catch (error) {
      console.error("Error uploading document:", error);
      res.status(500).json({ error: "Failed to upload document" });
    }
  });

  // Favorites endpoints
  app.get("/api/users/:userId/favorites", async (req, res) => {
    try {
      const { userId } = req.params;

      if (!userId) {
        return res.status(400).json({ error: "User ID is required" });
      }

      const favorites = await storage.getUserFavorites(parseInt(userId));
      res.json(favorites);
    } catch (error) {
      console.error("Error fetching user favorites:", error);
      res.status(500).json({ error: "Failed to fetch favorites" });
    }
  });

  app.post("/api/users/:userId/favorites", async (req, res) => {
    try {
      const { userId } = req.params;
      const { propertyId } = req.body;

      if (!userId || !propertyId) {
        return res.status(400).json({ error: "User ID and property ID are required" });
      }

      // Check if property exists
      const property = await storage.getProperty(propertyId);
      if (!property) {
        return res.status(404).json({ error: "Property not found" });
      }

      // Check if already favorited
      const isAlreadyFavorited = await storage.isPropertyFavorited(parseInt(userId), propertyId);
      if (isAlreadyFavorited) {
        return res.status(409).json({ error: "Property already in favorites" });
      }

      const favorite = await storage.addToFavorites(parseInt(userId), propertyId);

      // Create notification for property owner that their property was favorited
      if (property.ownerId && property.ownerId !== parseInt(userId)) {
        await storage.createNotification({
          userId: property.ownerId,
          title: "Propriété mise en favoris",
          message: `Votre propriété "${property.title}" a été ajoutée aux favoris par un utilisateur.`,
          type: "property_favorite",
          relatedId: propertyId,
        });
      }

      // Broadcast real-time update via WebSocket
      const ws = wsConnections.get(parseInt(userId));
      if (ws) {
        ws.send(JSON.stringify({ 
          event: 'favorite_added', 
          data: { propertyId, property } 
        }));
      }

      res.status(201).json({ message: "Property added to favorites", favorite });
    } catch (error) {
      console.error("Error adding to favorites:", error);
      res.status(500).json({ error: "Failed to add to favorites" });
    }
  });

  app.delete("/api/users/:userId/favorites/:propertyId", async (req, res) => {
    try {
      const { userId, propertyId } = req.params;

      if (!userId || !propertyId) {
        return res.status(400).json({ error: "User ID and property ID are required" });
      }

      const removed = await storage.removeFromFavorites(parseInt(userId), parseInt(propertyId));

      if (!removed) {
        return res.status(404).json({ error: "Favorite not found" });
      }

      // Broadcast real-time update via WebSocket
      const ws = wsConnections.get(parseInt(userId));
      if (ws) {
        ws.send(JSON.stringify({ 
          event: 'favorite_removed', 
          data: { propertyId: parseInt(propertyId) } 
        }));
      }

      res.json({ message: "Property removed from favorites" });
    } catch (error) {
      console.error("Error removing from favorites:", error);
      res.status(500).json({ error: "Failed to remove from favorites" });
    }
  });

  app.get("/api/users/:userId/favorites/:propertyId/check", async (req, res) => {
    try {
      const { userId, propertyId } = req.params;

      if (!userId || !propertyId) {
        return res.status(400).json({ error: "User ID and property ID are required" });
      }

      const isFavorited = await storage.isPropertyFavorited(parseInt(userId), parseInt(propertyId));
      res.json({ isFavorited });
    } catch (error) {
      console.error("Error checking favorite status:", error);
      res.status(500).json({ error: "Failed to check favorite status" });
    }
  });

  // Dashboard Stats API
  app.get("/api/dashboard/stats/:userId", requireAuth, async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);
      const userType = req.query.userType as string;

      if (userType === 'owner') {
        // Owner dashboard stats
        const properties = await storage.getPropertiesByOwner(userId);
        const contracts = await storage.getContractsByOwner(userId);
        const activeContracts = contracts.filter(c => c.status === 'active');
        const monthlyRevenue = activeContracts.reduce((sum, c) => sum + parseFloat(c.monthlyRent || '0'), 0);
        const occupancyRate = properties.length > 0 ? Math.round((activeContracts.length / properties.length) * 100) : 0;

        // Calculate views for all properties
        const totalViews = properties.reduce((sum, p) => sum + (p.views || 0), 0);

        res.json({
          totalProperties: properties.length,
          activeContracts: activeContracts.length,
          monthlyRevenue,
          occupancyRate,
          totalViews,
          properties: properties.slice(0, 3), // Latest 3 properties
          recentActivity: {
            newMessages: contracts.length, // Simplified count
            viewsThisMonth: totalViews,
            applicationsCount: 0 // Will be calculated from offers
          }
        });
      } else {
        // Tenant dashboard stats  
        const favorites = await storage.getFavoritesByUser(userId);
        const contracts = await storage.getContractsByTenant(userId);
        const activeContracts = contracts.filter(c => c.status === 'active');
        const offers = await storage.getOffersByUser(userId, 'tenant');

        res.json({
          favoritesCount: favorites.length,
          activeContracts: activeContracts.length,
          offersCount: offers.length,
          favorites: favorites.slice(0, 3), // Latest 3 favorites
          recentActivity: {
            newProperties: 0, // Will be calculated based on recent additions
            messagesCount: contracts.length, // Simplified
            applicationStatus: offers.filter(o => o.status === 'pending').length
          }
        });
      }
    } catch (error) {
      console.error('Dashboard stats error:', error);
      res.status(500).json({ error: 'Failed to fetch dashboard stats' });
    }
  });

  // Dashboard Analytics API
  app.get("/api/dashboard/analytics/:userId", requireAuth, async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);
      const userType = req.query.userType as string;

      if (userType === 'owner') {
        const properties = await storage.getPropertiesByOwner(userId);
        const contracts = await storage.getContractsByOwner(userId);

        // Monthly revenue trend (simplified for now)
        const monthlyData = [
          { month: 'Jan', revenue: Math.floor(Math.random() * 2000) + 500 },
          { month: 'Feb', revenue: Math.floor(Math.random() * 2000) + 600 },
          { month: 'Mar', revenue: Math.floor(Math.random() * 2000) + 700 },
          { month: 'Apr', revenue: Math.floor(Math.random() * 2000) + 800 },
          { month: 'May', revenue: Math.floor(Math.random() * 2000) + 900 },
          { month: 'Jun', revenue: contracts.reduce((sum, c) => sum + parseFloat(c.monthlyRent || '0'), 0) }
        ];

        // Property views data
        const viewsData = properties.map(p => ({
          property: p.title.substring(0, 20) + '...',
          views: p.views || Math.floor(Math.random() * 200) + 50,
          inquiries: Math.floor(Math.random() * 15) + 2
        }));

        res.json({
          monthlyRevenue: monthlyData,
          propertyViews: viewsData,
          occupancyTrend: [
            { month: 'Jan', rate: 70 },
            { month: 'Feb', rate: 75 },
            { month: 'Mar', rate: 80 },
            { month: 'Apr', rate: 85 },
            { month: 'May', rate: 90 },
            { month: 'Jun', rate: properties.length > 0 ? Math.round((contracts.filter(c => c.status === 'active').length / properties.length) * 100) : 0 }
          ]
        });
      } else {
        // Tenant analytics - search activity, favorites, etc.
        const favorites = await storage.getFavoritesByUser(userId);

        res.json({
          searchActivity: [
            { week: 'W1', searches: 5 },
            { week: 'W2', searches: 8 },
            { week: 'W3', searches: 12 },
            { week: 'W4', searches: 7 }
          ],
          favoritesByType: [
            { type: 'Studio', count: favorites.filter(f => f.property?.type === 'studio').length || 2 },
            { type: 'Appartement', count: favorites.filter(f => f.property?.type === 'apartment').length || 3 },
            { type: 'Maison', count: favorites.filter(f => f.property?.type === 'house').length || 1 }
          ]
        });
      }
    } catch (error) {
      console.error('Dashboard analytics error:', error);
      res.status(500).json({ error: 'Failed to fetch dashboard analytics' });
    }
  });

  // Dashboard stats endpoint
  app.get('/api/dashboard/stats/:userId', async (req, res) => {
    try {
      const { userId } = req.params;
      const { userType } = req.query;

      if (!userId || !userType) {
        return res.status(400).json({ error: 'Missing userId or userType' });
      }

      const userIdNum = parseInt(userId);
      let stats: any = {};

      if (userType === 'owner') {
        const properties = await storage.getPropertiesForOwner(userIdNum);
        const contracts = await storage.getOwnerContracts(userIdNum);
        const offers = await storage.getOffersByOwnerId(userIdNum);

        const totalViews = properties.reduce((sum: number, p: any) => sum + (p.views || 0), 0);
        const activeContracts = contracts.filter((c: any) => c.status === 'fully_signed' || c.status === 'active').length;
        const monthlyRevenue = contracts
          .filter((c: any) => c.status === 'fully_signed' || c.status === 'active')
          .reduce((sum: number, c: any) => sum + (parseInt(c.monthlyRent) || 0), 0);
        const occupancyRate = properties.length > 0 ? Math.round((activeContracts / properties.length) * 100) : 0;

        stats = {
          totalProperties: properties.length,
          totalViews,
          activeContracts,
          monthlyRevenue,
          occupancyRate,
          pendingOffers: offers.filter((o: any) => o.status === 'pending').length,
          totalOffers: offers.length
        };
      } else if (userType === 'tenant') {
        const contracts = await storage.getContractsByTenant(userIdNum);
        const offers = await storage.getOffersByTenantId(userIdNum);
        const favorites = await storage.getFavoritesByUser(userIdNum);
        const conversations = await storage.getConversationsByUser(userIdNum);

        stats = {
          activeContracts: contracts.filter((c: any) => c.status === 'fully_signed' || c.status === 'active').length,
          favoritesCount: favorites.length,
          offersCount: offers.length,
          recentActivity: {
            messagesCount: conversations.length,
            lastActivity: new Date().toISOString()
          }
        };
      }

      res.json(stats);
    } catch (error) {
      console.error('Dashboard stats error:', error);
      res.status(500).json({ error: 'Failed to fetch dashboard stats' });
    }
  });

  // Property visibility enhancement endpoint  
  app.post('/api/properties/:id/boost', async (req, res) => {
    try {
      const propertyId = parseInt(req.params.id);
      const { boostType = 'featured', duration = 7 } = req.body;

      const property = await storage.getProperty(propertyId);
      if (!property) {
        return res.status(404).json({ error: 'Property not found' });
      }

      // Update property with boost
      const boostedUntil = new Date();
      boostedUntil.setDate(boostedUntil.getDate() + duration);

      const updatedProperty = await storage.updateProperty(propertyId, {
        isFeatured: boostType === 'featured',
        featuredUntil: boostedUntil,
        boostLevel: boostType === 'premium' ? 2 : 1,
        updatedAt: new Date()
      });

      // Create notification for property owner
      await storage.createNotification({
        userId: property.ownerId,
        title: "Propriété mise en avant",
        message: `Votre propriété "${property.title}" est maintenant mise en avant pour ${duration} jours.`,
        type: "property_boost",
        relatedId: propertyId,
      });

      res.json({ 
        message: 'Property boost applied successfully',
        property: updatedProperty,
        boostedUntil
      });
    } catch (error) {
      console.error('Property boost error:', error);
      res.status(500).json({ error: 'Failed to boost property' });
    }
  });

  // Get recommended properties for better reach
  app.get('/api/properties/recommendations/:userId', async (req, res) => {
    try {
      const { userId } = req.params;
      const { userType = 'tenant' } = req.query;

      const userIdNum = parseInt(userId);
      let recommendations: any[] = [];

      if (userType === 'tenant') {
        // Get user's favorites to understand preferences
        const favorites = await storage.getFavoritesByUser(userIdNum);
        const allProperties = await storage.getProperties();

        // Simple recommendation based on user's favorite types and locations
        const favoriteTypes = [...new Set(favorites.map((f: any) => f.property?.type).filter(Boolean))];
        const favoriteLocations = [...new Set(favorites.map((f: any) => f.property?.address?.split(',')[0]).filter(Boolean))];

        recommendations = allProperties
          .filter((p: any) => 
            !favorites.some((f: any) => f.propertyId === p.id) && // Not already favorited
            (favoriteTypes.length === 0 || favoriteTypes.includes(p.type) || 
             favoriteLocations.length === 0 || favoriteLocations.some((loc: string) => p.address?.includes(loc)))
          )
          .sort((a: any, b: any) => (b.views || 0) - (a.views || 0)) // Sort by popularity
          .slice(0, 10);
      } else {
        // For owners, recommend similar properties for comparison
        const ownProperties = await storage.getPropertiesForOwner(userIdNum);
        if (ownProperties.length > 0) {
          const allProperties = await storage.getProperties();
          const avgPrice = ownProperties.reduce((sum: number, p: any) => sum + (parseInt(p.price) || 0), 0) / ownProperties.length;

          recommendations = allProperties
            .filter((p: any) => p.ownerId !== userIdNum)
            .filter((p: any) => Math.abs((parseInt(p.price) || 0) - avgPrice) < avgPrice * 0.3) // Within 30% price range
            .sort((a: any, b: any) => (b.views || 0) - (a.views || 0))
            .slice(0, 8);
        }
      }

      res.json(recommendations);
    } catch (error) {
      console.error('Recommendations error:', error);
      res.status(500).json({ error: 'Failed to fetch recommendations' });
    }
  });

  // User profile endpoints
  app.get('/api/users/:userId/profile', async (req, res) => {
    try {
      const { userId } = req.params;

      if (!userId) {
        return res.status(400).json({ error: 'User ID is required' });
      }

      const user = await storage.getUser(parseInt(userId));
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      // Return public user profile (exclude sensitive information)
      const publicProfile = {
        id: user.id,
        username: user.username,
        firstName: user.firstName,
        lastName: user.lastName,
        userType: user.userType,
        bio: user.bio,
        profilePicture: user.profilePicture,
        isVerified: user.emailVerified && user.phoneVerified,
        verificationLevel: getUserVerificationLevel(user),
        trustScore: calculateTrustScore(user),
        rating: user.rating,
        responseRate: user.responseTime === 'fast' ? '95' : user.responseTime === 'normal' ? '80' : '60',
        avgResponseTime: user.responseTime === 'fast' ? 2 : user.responseTime === 'normal' ? 8 : 24,
        contractsCount: user.contractsCount || 0,
        badges: getUserBadges(user),
        createdAt: user.createdAt,
        // Only show phone/email to authenticated users viewing their own profile or in specific contexts
        ...(req.headers.authorization && { phone: user.phoneVerified ? user.phone : null }),
      };

      res.json(publicProfile);
    } catch (error) {
      console.error('Get user profile error:', error);
      res.status(500).json({ error: 'Failed to fetch user profile' });
    }
  });

  // Helper functions for user profile
  function getUserVerificationLevel(user: any): string {
    if (user.documentVerified) return 'identity';
    if (user.phoneVerified && user.emailVerified) return 'phone';
    if (user.emailVerified) return 'email';
    return 'none';
  }

  function calculateTrustScore(user: any): number {
    let score = 50; // Base score

    if (user.emailVerified) score += 10;
    if (user.phoneVerified) score += 15;
    if (user.documentVerified) score += 20;

    const rating = parseFloat(user.rating || '0');
    if (rating >= 4.5) score += 15;
    else if (rating >= 4.0) score += 10;
    else if (rating >= 3.5) score += 5;

    if (user.contractsCount >= 10) score += 10;
    else if (user.contractsCount >= 5) score += 5;

    if (user.responseTime === 'fast') score += 10;
    else if (user.responseTime === 'normal') score += 5;

    return Math.min(100, Math.max(0, score));
  }

  function getUserBadges(user: any): any[] {
    const badges = [];

    if (user.emailVerified && user.phoneVerified) {
      badges.push({ type: 'verified', label: 'Vérifié', color: 'blue' });
    }

    if (user.documentVerified) {
      badges.push({ type: 'identity', label: 'Identité vérifiée', color: 'green' });
    }

    const rating = parseFloat(user.rating || '0');
    if (rating >= 4.5) {
      badges.push({ type: 'top_rated', label: 'Top noté', color: 'gold' });
    }

    if (user.responseTime === 'fast') {
      badges.push({ type: 'responsive', label: 'Réactif', color: 'green' });
    }

    if (user.contractsCount >= 10) {
      badges.push({ type: 'experienced', label: 'Expérimenté', color: 'purple' });
    }

    return badges;
  }

  const httpServer = createServer(app);

  // WebSocket server setup with authentication and real-time events
  const wss = new WebSocketServer({ server: httpServer, path: '/ws' });

  wss.on('connection', (ws: WebSocket, req) => {
    console.log('WebSocket client connected');

    ws.on('message', (message: string) => {
      try {
        const data = JSON.parse(message);

        if (data.type === 'auth' && data.token) {
          // Authenticate the WebSocket connection
          const tokenParts = data.token.split('_');
          if (tokenParts.length >= 4 && tokenParts[0] === 'session') {
            const userId = parseInt(tokenParts[1]);
            const userType = tokenParts[2];

            // Store authenticated connection
            wsConnections.set(userId, ws);
            wsAuthenticated.set(ws, userId);

            console.log(`User ${userId} (${userType}) authenticated on WebSocket`);
            ws.send(JSON.stringify({ event: 'auth_success', data: { userId, userType } }));

            // Send initial data
            ws.send(JSON.stringify({ event: 'connection_established', data: { userId, timestamp: new Date().toISOString() } }));
          } else {
            ws.send(JSON.stringify({ event: 'auth_error', data: { message: 'Invalid token' } }));
            ws.close();
          }
        }
      } catch (error) {
        console.error('WebSocket message error:', error);
      }
    });

    ws.on('close', () => {
      const userId = wsAuthenticated.get(ws);
      if (userId) {
        wsConnections.delete(userId);
        wsAuthenticated.delete(ws);
        console.log(`User ${userId} disconnected from WebSocket`);
      }
    });

    ws.on('error', (error) => {
      console.error('WebSocket error:', error);
      const userId = wsAuthenticated.get(ws);
      if (userId) {
        wsConnections.delete(userId);
        wsAuthenticated.delete(ws);
      }
    });
  });

  return httpServer;
}

