import { useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useLocation } from 'wouter';

interface AutomaticTenantNavigationProps {
  userId: number;
  userType: string;
}

export function AutomaticTenantNavigation({ userId, userType }: AutomaticTenantNavigationProps) {
  const [location, navigate] = useLocation();

  // Only works for tenants
  const { data: notifications = [] } = useQuery({
    queryKey: ['/api/notifications'],
    enabled: userType === 'tenant',
    refetchInterval: 5000 // Check every 5 seconds
  });

  useEffect(() => {
    if (userType !== 'tenant') return;

    // Look for new contract management request notifications
    const managementNotifications = notifications.filter((notification: any) => 
      (notification.type === 'contract_modification_request' || 
       notification.type === 'contract_termination_request') &&
      notification.isRead === false
    );

    // If there's a new management request notification and we're not already on the response page
    if (managementNotifications.length > 0 && !location.includes('/tenant-requests/')) {
      const latestNotification = managementNotifications[0];

      // Determine request type and navigate to response page
      const requestType = latestNotification.type === 'contract_modification_request' 
        ? 'modification' 
        : 'termination';

      // Navigate to the tenant response page
      navigate(`/tenant-requests/${requestType}/${latestNotification.relatedId}`);
    }
  }, [notifications, userType, location, navigate]);

  return null; // This component doesn't render anything
}

client/src/components/BadgeSystem.tsx.content:
import React from "react";
import { Badge } from "@/components/ui/badge";
import { Star, CheckCircle, Calendar, Award, MessageCircle, Crown } from "lucide-react";

interface UserBadgesProps {
  userType: string;
  isVerified?: boolean;
  contractsCount?: number;
  rating?: number;
  responseTime?: string;
  memberSince?: string;
  className?: string;
}

interface PropertyBadgeProps {
  propertyType: "priority" | "best" | "new" | "editor" | "normal";
  className?: string;
}

export const UserBadges: React.FC<UserBadgesProps> = ({
  userType,
  isVerified = false,
  contractsCount = 0,
  rating = 0,
  responseTime,
  memberSince,
  className = ""
}) => {
  const badges = [];

  // Badge compte vérifié
  if (isVerified) {
    badges.push({
      label: "Compte vérifié",
      icon: <CheckCircle className="h-3 w-3" />,
      variant: "default" as const,
      emoji: "✅"
    });
  }

  // Badge super propriétaire
  if (userType === "owner" && rating >= 4.5 && contractsCount >= 5) {
    badges.push({
      label: "Super propriétaire",
      icon: <Crown className="h-3 w-3" />,
      variant: "default" as const,
      emoji: "🌟"
    });
  }

  // Badge propriétaire actif
  if (userType === "owner" && contractsCount > 0) {
    badges.push({
      label: "Propriétaire actif",
      icon: <Award className="h-3 w-3" />,
      variant: "secondary" as const,
      emoji: "📷"
    });
  }

  // Badge contrats signés
  if (contractsCount > 0) {
    badges.push({
      label: `${contractsCount} contrat${contractsCount > 1 ? 's' : ''} signé${contractsCount > 1 ? 's' : ''}`,
      icon: <Award className="h-3 w-3" />,
      variant: "outline" as const,
      emoji: "🧾"
    });
  }

  // Badge réactif
  if (responseTime === "fast") {
    badges.push({
      label: "Réactif",
      icon: <MessageCircle className="h-3 w-3" />,
      variant: "secondary" as const,
      emoji: "💬"
    });
  }

  // Badge ancienneté
  if (memberSince) {
    const years = new Date().getFullYear() - new Date(memberSince).getFullYear();
    if (years >= 1) {
      badges.push({
        label: `${years} an${years > 1 ? 's' : ''} d'ancienneté`,
        icon: <Calendar className="h-3 w-3" />,
        variant: "outline" as const,
        emoji: "🎖"
      });
    }
  }

  return (
    <div className={`flex flex-wrap gap-1 ${className}`}>
      {badges.map((badge, index) => (
        <Badge key={index} variant={badge.variant} className="text-xs flex items-center gap-1">
          <span>{badge.emoji}</span>
          <span>{badge.label}</span>
        </Badge>
      ))}
    </div>
  );
};

export const PropertyBadge: React.FC<PropertyBadgeProps> = ({ propertyType, className = "" }) => {
  const getBadgeConfig = () => {
    switch (propertyType) {
      case "priority":
        return {
          label: "Prioritaire",
          emoji: "🔝",
          variant: "default" as const,
          description: "Super propriétaire"
        };
      case "best":
        return {
          label: "Best of",
          emoji: "🌟",
          variant: "default" as const,
          description: "Meilleur avis"
        };
      case "new":
        return {
          label: "Nouveau",
          emoji: "🆕",
          variant: "secondary" as const,
          description: "Moins de 7 jours"
        };
      case "editor":
        return {
          label: "Choix de la rédaction",
          emoji: "📌",
          variant: "outline" as const,
          description: "Sélection manuelle"
        };
      default:
        return null;
    }
  };

  const config = getBadgeConfig();
  if (!config) return null;

  return (
    <Badge variant={config.variant} className={`text-xs flex items-center gap-1 ${className}`}>
      <span>{config.emoji}</span>
      <span>{config.label}</span>
    </Badge>
  );
};

export const getPropertyBadgeType = (property: any): "priority" | "best" | "new" | "editor" | "normal" => {
  // Propriété nouvelle (moins de 7 jours)
  const createdDate = new Date(property.createdAt || Date.now());
  const daysDiff = Math.floor((Date.now() - createdDate.getTime()) / (1000 * 60 * 60 * 24));

  if (daysDiff <= 7) {
    return "new";
  }

  // Best of (rating élevé)
  if (property.rating >= 4.8 && property.reviews >= 10) {
    return "best";
  }

  // Prioritaire (super propriétaire)
  if (property.owner?.isVerified && property.owner?.rating >= 4.5) {
    return "priority";
  }

  // Choix de la rédaction (flag spécial)
  if (property.editorChoice) {
    return "editor";
  }

  return "normal";
};

client/src/components/ContractActions.ts.content:
import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { useToast } from "@/hooks/use-toast";
import { Download, Edit, Trash2, Clock, AlertTriangle, FileX } from "lucide-react";
import ContractGenerator from "./ContractGenerator";

interface Contract {
  id: number;
  status: string;
  contractData: any;
  tenantSignDeadline?: string | null;
}

interface ContractActionsProps {
  contract: Contract;
  currentUserId: number;
  isOwner: boolean;
}

export function ContractActions({ contract, currentUserId, isOwner }: ContractActionsProps) {
  const { toast } = useToast();
  const [isModifyDialogOpen, setIsModifyDialogOpen] = useState(false);

  // Download PDF mutation
  const downloadMutation = useMutation({
    mutationFn: async () => {
      const response = await fetch(`/api/contracts/${contract.id}/download`, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' }
      });
      if (!response.ok) throw new Error('Failed to generate download link');
      return response.json();
    },
    onSuccess: (data) => {
      // In a real implementation, this would trigger the actual PDF download
      toast({
        title: "Téléchargement prêt",
        description: `Le contrat ${data.filename} est prêt à être téléchargé.`,
      });

      // For demo purposes, show download URL
      console.log("Download URL:", data.downloadUrl);

      // In real implementation, you would trigger download:
      // window.open(data.downloadUrl, '_blank');
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible de télécharger le contrat",
        variant: "destructive",
      });
    }
  });

  // Contract modification mutation
  const modifyMutation = useMutation({
    mutationFn: async (newContractData: any) => {
      return apiRequest(`/api/contracts/${contract.id}/modify`, {
        method: 'PUT',
        body: JSON.stringify({ contractData: newContractData })
      });
    },
    onSuccess: () => {
      toast({
        title: "Contrat modifié",
        description: "Le contrat a été modifié avec succès. Les signatures ont été supprimées.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/contracts', contract.id] });
      setIsModifyDialogOpen(false);
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible de modifier le contrat",
        variant: "destructive",
      });
    }
  });

  // Early termination request mutation
  const terminationRequestMutation = useMutation({
    mutationFn: async () => {
      return apiRequest(`/api/contracts/${contract.id}/request-termination`, {
        method: 'POST',
        body: JSON.stringify({
          requestedBy: currentUserId,
          reason: "Demande d'arrêt anticipé par le propriétaire"
        })
      });
    },
    onSuccess: () => {
      toast({
        title: "Demande envoyée",
        description: "Demande d'arrêt anticipé envoyée au locataire.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/contracts', contract.id] });
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible d'envoyer la demande",
        variant: "destructive",
      });
    }
  });

  // Modification request mutation
  const modificationRequestMutation = useMutation({
    mutationFn: async () => {
      return apiRequest(`/api/contracts/${contract.id}/request-modification`, {
        method: 'POST',
        body: JSON.stringify({
          requestedBy: currentUserId,
          requestedChanges: "Demande de modification des termes du contrat"
        })
      });
    },
    onSuccess: () => {
      toast({
        title: "Demande envoyée",
        description: "Demande de modification envoyée au locataire.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/contracts', contract.id] });
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible d'envoyer la demande",
        variant: "destructive",
      });
    }
  });

  const canDownload = contract.status === 'active' || contract.status === 'fully_signed';
  const canModify = isOwner && (contract.status === 'draft' || contract.status === 'owner_signed');
  const isExpired = contract.tenantSignDeadline && new Date() > new Date(contract.tenantSignDeadline);
  const isActive = contract.status === 'active' || contract.status === 'fully_signed';
  const canRequestTermination = isOwner && isActive;
  const canRequestModification = isOwner && isActive;

  // Tenants have very limited actions - only download when fully signed
  const isTenant = !isOwner;

  return (
    <div className="flex items-center gap-2">
      {/* Download PDF Button */}
      {canDownload && (
        <Button
          variant="outline"
          size="sm"
          onClick={() => downloadMutation.mutate()}
          disabled={downloadMutation.isPending}
        >
          <Download className="h-4 w-4 mr-2" />
          {downloadMutation.isPending ? "Génération..." : "Télécharger PDF"}
        </Button>
      )}

      {/* Modify Contract Button - Only for owners */}
      {canModify && !isExpired && !isTenant && (
        <Dialog open={isModifyDialogOpen} onOpenChange={setIsModifyDialogOpen}>
          <DialogTrigger asChild>
            <Button variant="outline" size="sm">
              <Edit className="h-4 w-4 mr-2" />
              Modifier
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Modifier le contrat</DialogTitle>
            </DialogHeader>
            <div className="mt-4">
              <ContractGenerator
                initialData={contract.contractData}
                onSave={(contractData: any) => modifyMutation.mutate(contractData)}
                isLoading={modifyMutation.isPending}
                mode="modify"
                currentUserId={currentUserId}
              />
            </div>
          </DialogContent>
        </Dialog>
      )}

      {/* Early Termination Request - Only for owners of active contracts */}
      {canRequestTermination && !isTenant && (
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button variant="outline" size="sm" className="border-orange-500 text-orange-600 hover:bg-orange-50">
              <Clock className="h-4 w-4 mr-2" />
              Arrêt anticipé
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle className="flex items-center gap-2">
                <AlertTriangle className="h-5 w-5 text-orange-500" />
                Demander un arrêt anticipé
              </AlertDialogTitle>
              <AlertDialogDescription className="space-y-2">
                <p>Vous êtes sur le point de demander un arrêt anticipé de ce contrat.</p>
                <div className="bg-orange-50 p-3 rounded-lg border-l-4 border-orange-400">
                  <p className="text-sm text-orange-700">
                    <strong>Important :</strong> Le locataire doit accepter cette demande pour que l'arrêt soit effectif. 
                    Si accepté, le contrat sera immédiatement terminé et le bien redeviendra disponible.
                  </p>
                </div>
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Annuler</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => terminationRequestMutation.mutate()}
                disabled={terminationRequestMutation.isPending}
                className="bg-orange-600 hover:bg-orange-700"
              >
                {terminationRequestMutation.isPending ? "Envoi..." : "Envoyer la demande"}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}

      {/* Modification Request - Only for owners of active contracts */}
      {canRequestModification && !isTenant && (
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button variant="outline" size="sm" className="border-blue-500 text-blue-600 hover:bg-blue-50">
              <Edit className="h-4 w-4 mr-2" />
              Demander modification
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle className="flex items-center gap-2">
                <Edit className="h-5 w-5 text-blue-500" />
                Demander une modification
              </AlertDialogTitle>
              <AlertDialogDescription className="space-y-2">
                <p>Vous allez demander au locataire l'autorisation de modifier ce contrat.</p>
                <div className="bg-blue-50 p-3 rounded-lg border-l-4 border-blue-400">
                  <p className="text-sm text-blue-700">
                    <strong>Note :</strong> Le locataire doit approuver votre demande avant que vous puissiez 
                    modifier le contrat. Les signatures seront supprimées après modification.
                  </p>
                </div>
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Annuler</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => modificationRequestMutation.mutate()}
                disabled={modificationRequestMutation.isPending}
                className="bg-blue-600 hover:bg-blue-700"
              >
                {modificationRequestMutation.isPending ? "Envoi..." : "Envoyer la demande"}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}

      {/* Cancel/Delete Contract - Only for owners */}
      {(isOwner && !isTenant && (contract.status === 'draft' || isExpired)) && (
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button variant="destructive" size="sm">
              <Trash2 className="h-4 w-4 mr-2" />
              {isExpired ? "Supprimer" : "Annuler"}
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Confirmer la suppression</AlertDialogTitle>
              <AlertDialogDescription>
                Êtes-vous sûr de vouloir {isExpired ? "supprimer" : "annuler"} ce contrat ? 
                Cette action est irréversible.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Annuler</AlertDialogCancel>
              <AlertDialogAction
                onClick={() => {
                  // In real implementation, add delete/cancel mutation
                  toast({
                    title: "Contrat supprimé",
                    description: "Le contrat a été supprimé avec succès.",
                  });
                }}
              >
                Confirmer
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}
    </div>
  );
}

