import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import SignatureCanvas from "react-signature-canvas";
import { FileText, Download, PenTool, X } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";

interface ContractGeneratorProps {
  contract?: any;
  onSign?: (signatureData: any) => void;
  isLoading?: boolean;
  currentUserId?: number;
  // For modification mode
  initialData?: any;
  onSave?: (contractData: any) => void;
  mode?: 'view' | 'modify';
}

export default function ContractGenerator({ 
  contract, 
  onSign, 
  isLoading = false, 
  currentUserId = 1,
  initialData,
  onSave,
  mode = 'view'
}: ContractGeneratorProps) {
  const [signatureCanvas, setSignatureCanvas] = useState<SignatureCanvas | null>(null);
  const [showSignatureCanvas, setShowSignatureCanvas] = useState(false);
  const { toast } = useToast();

  // Handle different modes
  const contractData = contract || initialData;

  // Early return if no contract data is available
  if (!contractData) {
    return (
      <Card>
        <CardContent className="py-8">
          <div className="text-center text-muted-foreground">
            Chargement du contrat...
          </div>
        </CardContent>
      </Card>
    );
  }

  // For modify mode, handle the contract data differently
  if (mode === 'modify' && initialData) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Modification du contrat</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="text-sm text-muted-foreground mb-4">
              La fonctionnalité de modification est en cours de développement.
            </div>
            <Button 
              onClick={() => onSave && onSave(initialData)}
              disabled={isLoading}
            >
              {isLoading ? "Enregistrement..." : "Enregistrer les modifications"}
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Determine user role based on contract data
  const userRole: 'owner' | 'tenant' = currentUserId === contractData.ownerId ? 'owner' : 'tenant';

  const canSign = () => {
    if (userRole === 'owner') {
      // Owner can sign if they haven't signed yet, regardless of contract status
      return !contractData.ownerSignature;
    } else if (userRole === 'tenant') {
      // Tenant can sign if owner has signed but tenant hasn't
      return contractData.ownerSignature && !contractData.tenantSignature;
    }
    return false;
  };

  const handleSign = () => {
    if (!signatureCanvas || signatureCanvas.isEmpty()) {
      toast({
        title: "Signature requise",
        description: "Veuillez signer avant de valider",
        variant: "destructive",
      });
      return;
    }

    const signatureData = signatureCanvas.toDataURL();
    onSign && onSign({
      signatureType: userRole,
      signatureData: signatureData
    });
    setShowSignatureCanvas(false);

    toast({
      title: "Signature enregistrée",
      description: "Votre signature a été ajoutée au contrat",
    });
  };

  const clearSignature = () => {
    if (signatureCanvas) {
      signatureCanvas.clear();
    }
  };

  const generatePDF = async () => {
    const contractElement = document.getElementById('contract-content');
    if (!contractElement) return;

    try {
      const canvas = await html2canvas(contractElement);
      const imgData = canvas.toDataURL('image/png');

      const pdf = new jsPDF();
      const imgWidth = 210;
      const pageHeight = 295;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;

      let position = 0;

      pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      while (heightLeft >= 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      pdf.save(`contrat-${contractData.id || 'draft'}.pdf`);

      toast({
        title: "PDF généré",
        description: "Le contrat a été téléchargé avec succès",
      });
    } catch (error) {
      toast({
        title: "Erreur",
        description: "Impossible de générer le PDF",
        variant: "destructive",
      });
    }
  };

  return (
    <div className="space-y-6">
      {/* Contract Display */}
      <Card className="glass-card">
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <FileText className="h-5 w-5" />
            <span>Contrat de Location #{contractData.id || 'draft'}</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div id="contract-content" className="space-y-4 text-sm max-w-4xl mx-auto p-6 bg-white text-black">
            <div className="text-center font-bold text-xl mb-8">
              CONTRAT DE LOCATION
            </div>

            <div className="text-center mb-6">
              <p>Pour</p>
              <p className="font-semibold">un appartement meublé/non meublé</p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">ENTRE LES SOUSSIGNÉS :</p>
              <div className="ml-4 space-y-2">
                <p><strong>Le BAILLEUR:</strong> M. {contractData.contractData?.landlordName || contractData.landlordName || "Propriétaire"}</p>
                {(contractData.contractData?.landlordCin || contractData.landlordCin) && (
                  <p className="ml-4">CIN: {contractData.contractData?.landlordCin || contractData.landlordCin}</p>
                )}
                <p><strong>Le PRENEUR:</strong> M. {contractData.contractData?.tenantName || contractData.tenantName || "Locataire"}</p>
                {(contractData.contractData?.tenantCin || contractData.tenantCin) && (
                  <p className="ml-4">CIN: {contractData.contractData?.tenantCin || contractData.tenantCin}</p>
                )}
              </div>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">IL A ÉTÉ CONVENU CE QUI SUIT :</p>
              <div className="ml-4 space-y-2">
                <p>Le bailleur loue à M. {contractData.contractData?.tenantName || contractData.tenantName || "Locataire"}</p>
                <p><strong>Propriété:</strong> {contractData.contractData?.propertyTitle || contractData.propertyTitle || "Propriété"}</p>
                <p><strong>Adresse:</strong> {contractData.contractData?.propertyAddress || contractData.propertyAddress || "Adresse non spécifiée"}</p>
              </div>
            </div>

            <div className="mb-6">
              <p>Il appartient aux deux parties de constater et d'établir, par acte séparé dressé contradictoirement, l'état des lieux et la connaissance du mobilier si les locaux sont loués meublés.</p>
            </div>

            <div className="mb-6">
              <p><strong>DURÉE DU BAIL:</strong></p>
              <p className="ml-4">
                Le bail est fait pour une durée déterminée du{" "}
                {(contractData.contractData?.startDate || contractData.startDate) ? new Date(contractData.contractData?.startDate || contractData.startDate).toLocaleDateString('fr-FR') : "__/__/__"}{" "}
                au{" "}
                {(contractData.contractData?.endDate || contractData.endDate) ? new Date(contractData.contractData?.endDate || contractData.endDate).toLocaleDateString('fr-FR') : "__/__/__"}
              </p>
            </div>

            <div className="mb-6">
              <p>Le preneur pourra le dénoncer avec un préavis de trois mois entiers par lettre recommandée avec accusé de réception pendant le contrat.</p>
              <p>Le bailleur pourra le dénoncer avec un préavis d'un mois entier par lettre recommandée avec accusé de réception pendant le contrat pour un motif sérieux et légitime et conformément aux dispositions prévues par la loi.</p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">OBLIGATIONS DU PRENEUR:</p>
              <p>Le présent contrat est fait aux conditions ordinaires et de droit en pareille matière à savoir la loi du 01/09/1948 ou les règles générales établies par le Code Civil. Le preneur et le bailleur s'engagent à respecter leurs obligations réciproques et notamment le preneur en vertu des obligations suivantes concernant le bon ordre et la tenue de l'immeuble et surtout l'entretien constant des locaux loués. Il devra payer le loyer au premier du mois.</p>
              <p><strong>Ce loyer s'élève actuellement à {contractData.contractData?.monthlyRent || contractData.monthlyRent || "___"} TND</strong></p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">CAUTION:</p>
              <p>Le montant de la caution s'élève à {contractData.contractData?.deposit || contractData.deposit || "___"} TND</p>
            </div>

            <div className="mb-6">
              <p className="font-semibold mb-2">CLAUSES SPÉCIALES:</p>
              <p>À défaut de paiement à son échéance d'un seul terme de loyer, comme en cas d'inexécution d'une des obligations mises à la charge du preneur tant par la présente convention que par la loi et deux mois après un commandement de payer ou sommation, déférée par le bailleur, demeure sans effet, la présente location sera résiliée de plein droit sans qu'il y ait à remplir aucune formalité judiciaire.</p>
              <p>Le preneur ne peut en aucun cas procéder à une sous-location ou échange de bail de son logement.</p>
            </div>

            {(contractData.contractData?.conditions || contractData.conditions || contractData.contractData?.specialConditions || contractData.specialConditions) && (
              <div className="mb-6">
                <p className="font-semibold mb-2">CONDITIONS PARTICULIÈRES:</p>
                <p className="ml-4">{contractData.contractData?.conditions || contractData.conditions || contractData.contractData?.specialConditions || contractData.specialConditions}</p>
              </div>
            )}

            <div className="mb-6">
              <p className="font-semibold">ANNEXE AU PRÉSENT CONTRAT:</p>
              <ul className="ml-4 list-disc">
                <li>Un état des lieux d'entrée plus inventaire (quand meublé)</li>
                <li>Un contrat de garantie</li>
              </ul>
            </div>

            <div className="mb-8">
              <p>Fait en trois exemplaires</p>
              <p>Le {new Date().toLocaleDateString('fr-FR')}</p>
            </div>

            {/* Signatures Section */}
            <div className="mt-12 border-t pt-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <div className="text-center">
                  <p className="font-semibold mb-4">LE BAILLEUR</p>
                  <p className="text-xs mb-2">(ajouter la mention lu et approuvé)</p>
                  {contractData.ownerSignature ? (
                    <div className="border rounded p-4 bg-white min-h-[100px] flex flex-col items-center justify-center">
                      <img src={contractData.ownerSignature} alt="Signature propriétaire" className="max-h-16 max-w-full" />
                      <p className="text-xs text-muted-foreground mt-2">
                        Signé le {contractData.ownerSignedAt ? new Date(contractData.ownerSignedAt).toLocaleDateString('fr-FR') : ''}
                      </p>
                    </div>
                  ) : (
                    <div className="border-2 border-dashed border-muted-foreground/30 rounded p-4 text-center text-muted-foreground min-h-[100px] flex items-center justify-center">
                      En attente de signature
                    </div>
                  )}
                </div>

                <div className="text-center">
                  <p className="font-semibold mb-4">LE PRENEUR</p>
                  <p className="text-xs mb-2">(ajouter la mention lu et approuvé)</p>
                  {contractData.tenantSignature ? (
                    <div className="border rounded p-4 bg-white min-h-[100px] flex flex-col items-center justify-center">
                      <img src={contractData.tenantSignature} alt="Signature locataire" className="max-h-16 max-w-full" />
                      <p className="text-xs text-muted-foreground mt-2">
                        Signé le {contractData.tenantSignedAt ? new Date(contractData.tenantSignedAt).toLocaleDateString('fr-FR') : ''}
                      </p>
                    </div>
                  ) : (
                    <div className="border-2 border-dashed border-muted-foreground/30 rounded p-4 text-center text-muted-foreground min-h-[100px] flex items-center justify-center">
                      En attente de signature
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Action Buttons - Role-based access */}
      <div className="flex justify-between items-center">
        {/* Download button for fully signed contracts */}
        {(contractData.ownerSignature && contractData.tenantSignature) && (
          <Button variant="outline" onClick={generatePDF}>
            <Download className="h-4 w-4 mr-2" />
            Télécharger PDF
          </Button>
        )}

        {/* Signing button - only show when it's the user's turn to sign */}
        {canSign() && (
          <Button onClick={() => setShowSignatureCanvas(true)} disabled={isLoading}>
            <PenTool className="h-4 w-4 mr-2" />
            {userRole === 'owner' ? 'Signer en tant que propriétaire' : 'Signer en tant que locataire'}
          </Button>
        )}

        {/* Status messages */}
        {userRole === 'tenant' && !contractData.ownerSignature && (
          <div className="text-sm text-muted-foreground">
            En attente de la signature du propriétaire
          </div>
        )}

        {userRole === 'owner' && contractData.ownerSignature && !contractData.tenantSignature && (
          <div className="text-sm text-muted-foreground">
            Contrat signé. En attente de la signature du locataire.
          </div>
        )}

        {contractData.ownerSignature && contractData.tenantSignature && (
          <div className="text-sm text-green-600 font-medium">
            Contrat entièrement signé et actif
          </div>
        )}
      </div>

      {/* Signature Modal */}
      {showSignatureCanvas && (
        <Card className="glass-card">
          <CardHeader>
            <CardTitle className="flex items-center justify-between">
              <span>Signature électronique</span>
              <Button variant="ghost" size="sm" onClick={() => setShowSignatureCanvas(false)}>
                <X className="h-4 w-4" />
              </Button>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <p className="text-sm text-muted-foreground">
                Signez dans l'espace ci-dessous avec votre souris ou votre doigt
              </p>

              <div className="border-2 border-dashed border-primary/20 rounded-lg">
                <SignatureCanvas
                  ref={(ref) => setSignatureCanvas(ref)}
                  canvasProps={{
                    width: 500,
                    height: 200,
                    className: 'signature-canvas w-full'
                  }}
                />
              </div>

              <div className="flex justify-between">
                <Button variant="outline" onClick={clearSignature}>
                  Effacer
                </Button>
                <Button onClick={handleSign} disabled={isLoading}>
                  {isLoading ? "Signature en cours..." : "Valider la signature"}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/components/ContractStatusBadg.content:
import { Badge } from "@/components/ui/badge";
import { Clock, CheckCircle, FileText, XCircle, AlertTriangle } from "lucide-react";

interface ContractStatusBadgeProps {
  status: string;
  tenantSignDeadline?: string | null;
}

export function ContractStatusBadge({ status, tenantSignDeadline }: ContractStatusBadgeProps) {
  const getStatusInfo = () => {
    switch (status) {
      case 'draft':
        return {
          label: 'Brouillon',
          variant: 'secondary' as const,
          icon: <FileText className="h-3 w-3" />
        };
      case 'owner_signed':
        const isExpired = tenantSignDeadline && new Date() > new Date(tenantSignDeadline);
        return {
          label: isExpired ? 'Expiré' : 'En attente locataire',
          variant: isExpired ? 'destructive' as const : 'default' as const,
          icon: isExpired ? <XCircle className="h-3 w-3" /> : <Clock className="h-3 w-3" />
        };
      case 'fully_signed':
        return {
          label: 'Signé complet',
          variant: 'default' as const,
          icon: <CheckCircle className="h-3 w-3" />
        };
      case 'active':
        return {
          label: 'Actif',
          variant: 'default' as const,
          icon: <CheckCircle className="h-3 w-3" />
        };
      case 'expired':
        return {
          label: 'Expiré',
          variant: 'destructive' as const,
          icon: <XCircle className="h-3 w-3" />
        };
      case 'cancelled':
        return {
          label: 'Annulé',
          variant: 'destructive' as const,
          icon: <XCircle className="h-3 w-3" />
        };
      default:
        return {
          label: status,
          variant: 'secondary' as const,
          icon: <AlertTriangle className="h-3 w-3" />
        };
    }
  };

  const { label, variant, icon } = getStatusInfo();

  return (
    <Badge variant={variant} className="flex items-center gap-1">
      {icon}
      {label}
    </Badge>
  );
}

client/src/components/ContractTerminatio.content:
import React from 'react';
import { CheckCircle, Circle, Clock } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface TerminationRequest {
  id: number;
  status: 'pending' | 'accepted' | 'rejected' | 'signed' | 'completed';
  ownerPasswordConfirmed: boolean;
  tenantPasswordConfirmed: boolean;
  ownerSignature?: string;
  tenantSignature?: string;
  ownerConfirmedAt?: string;
  tenantConfirmedAt?: string;
  ownerSignedAt?: string;
  tenantSignedAt?: string;
  createdAt?: string;
}

interface ContractTerminationProgressProps {
  request: TerminationRequest;
  currentUserType: 'owner' | 'tenant';
}

interface ProgressStep {
  id: string;
  title: string;
  completed: boolean;
  current?: boolean;
  date?: string;
}

export function ContractTerminationProgress({ request, currentUserType }: ContractTerminationProgressProps) {

  const getProgressSteps = (): ProgressStep[] => {
    const steps: ProgressStep[] = [
      {
        id: 'created',
        title: 'Demande créée',
        completed: true,
        date: request ? new Date(request.createdAt || '').toLocaleDateString('fr-FR') : undefined
      },
      {
        id: 'owner_confirmation',
        title: 'Confirmation propriétaire',
        completed: request?.ownerPasswordConfirmed || false,
        date: request?.ownerConfirmedAt ? new Date(request.ownerConfirmedAt).toLocaleDateString('fr-FR') : undefined
      },
      {
        id: 'tenant_confirmation', 
        title: 'Confirmation locataire',
        completed: request?.tenantPasswordConfirmed || false,
        date: request?.tenantConfirmedAt ? new Date(request.tenantConfirmedAt).toLocaleDateString('fr-FR') : undefined
      },
      {
        id: 'owner_signature',
        title: 'Signature propriétaire',
        completed: !!request?.ownerSignature,
        date: request?.ownerSignedAt ? new Date(request.ownerSignedAt).toLocaleDateString('fr-FR') : undefined
      },
      {
        id: 'tenant_signature',
        title: 'Signature locataire',
        completed: !!request?.tenantSignature,
        date: request?.tenantSignedAt ? new Date(request.tenantSignedAt).toLocaleDateString('fr-FR') : undefined
      }
    ];

    // Determine current step
    const firstIncompleteIndex = steps.findIndex(step => !step.completed);
    if (firstIncompleteIndex !== -1) {
      steps[firstIncompleteIndex].current = true;
    }

    return steps;
  };

  const steps = getProgressSteps();
  const allStepsCompleted = steps.every(step => step.completed);
  const currentStep = steps.find(step => step.current);

  const getStepIcon = (step: ProgressStep) => {
    if (step.completed) {
      return <CheckCircle className="w-5 h-5 text-green-600" />;
    } else if (step.current) {
      return <Clock className="w-5 h-5 text-blue-600" />;
    } else {
      return <Circle className="w-5 h-5 text-gray-400" />;
    }
  };

  const getStepStatus = (step: ProgressStep) => {
    if (step.completed) {
      return <Badge variant="secondary" className="bg-green-100 text-green-800">Terminé</Badge>;
    } else if (step.current) {
      return <Badge variant="secondary" className="bg-blue-100 text-blue-800">En cours</Badge>;
    } else {
      return <Badge variant="secondary" className="bg-gray-100 text-gray-600">En attente</Badge>;
    }
  };

  return (
    <div className="bg-white border rounded-lg p-6">
      <div className="mb-4">
        <h3 className="text-lg font-semibold">Processus d'arrêt de contrat</h3>
        <p className="text-sm text-gray-600">
          {allStepsCompleted ? 
            'Toutes les étapes sont terminées. Le contrat sera résilié.' :
            currentStep ? 
              `Étape actuelle: ${currentStep.title}` :
              'Processus d\'arrêt en cours'
          }
        </p>
      </div>

      <div className="space-y-4">
        {steps.map((step, index) => (
          <div key={step.id} className="flex items-center space-x-4">
            <div className="flex-shrink-0">
              {getStepIcon(step)}
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <p className={`text-sm font-medium ${
                    step.completed ? 'text-gray-900' : 
                    step.current ? 'text-blue-900' : 'text-gray-500'
                  }`}>
                    {step.title}
                  </p>
                  {getStepStatus(step)}
                </div>

                {step.date && (
                  <p className="text-xs text-gray-500">{step.date}</p>
                )}
              </div>

              {/* Progress line (except for last item) */}
              {index < steps.length - 1 && (
                <div className="ml-2.5 mt-2 h-6 w-px bg-gray-200"></div>
              )}
            </div>
          </div>
        ))}
      </div>

      {allStepsCompleted && (
        <div className="mt-6 p-4 bg-green-50 border border-green-200 rounded-lg">
          <div className="flex items-center">
            <CheckCircle className="w-5 h-5 text-green-600 mr-2" />
            <p className="text-sm font-medium text-green-800">
              Processus terminé - Le contrat sera officiellement résilié
            </p>
          </div>
        </div>
      )}

      {!allStepsCompleted && currentStep && (
        <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
          <div className="flex items-center">
            <Clock className="w-5 h-5 text-blue-600 mr-2" />
            <div>
              <p className="text-sm font-medium text-blue-800">
                En attente: {currentStep.title}
              </p>
              <p className="text-xs text-blue-600 mt-1">
                {currentStep.id.includes('confirmation') && 
                  'Veuillez confirmer avec votre mot de passe pour continuer'}
                {currentStep.id.includes('signature') && 
                  'Veuillez signer numériquement pour finaliser'}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { AlertCircle, CheckCircle, Lock, PenTool } from 'lucide-react';
import { ContractTerminationProgress } from './ContractTerminationProgress';
import SignatureCanvas from 'react-signature-canvas';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';

interface TerminationRequest {
  id: number;
  contractId: number;
  status: 'pending' | 'accepted' | 'rejected' | 'signed' | 'completed';
  ownerPasswordConfirmed: boolean;
  tenantPasswordConfirmed: boolean;
  ownerSignature?: string;
  tenantSignature?: string;
  ownerConfirmedAt?: string;
  tenantConfirmedAt?: string;
  ownerSignedAt?: string;
  tenantSignedAt?: string;
  createdAt?: string;
}

interface ContractTerminationWorkflowProps {
  request: TerminationRequest;
  currentUserType: 'owner' | 'tenant';
  currentUserId: number;
}

export function ContractTerminationWorkflow({ 
  request, 
  currentUserType, 
  currentUserId 
}: ContractTerminationWorkflowProps) {
  const [password, setPassword] = useState('');
  const [signatureRef, setSignatureRef] = useState<SignatureCanvas | null>(null);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  console.log('ContractTerminationWorkflow Debug:', {
    requestId: request.id,
    currentUserType,
    requestStatus: request.status,
    ownerPasswordConfirmed: request.ownerPasswordConfirmed,
    tenantPasswordConfirmed: request.tenantPasswordConfirmed,
    ownerSignature: !!request.ownerSignature,
    tenantSignature: !!request.tenantSignature,
    needsPasswordConfirmation: currentUserType === 'owner' ? !request.ownerPasswordConfirmed : !request.tenantPasswordConfirmed,
    needsSignature: currentUserType === 'owner' ? !request.ownerSignature && request.ownerPasswordConfirmed : !request.tenantSignature && request.tenantPasswordConfirmed,
    canConfirmPassword: request.status === 'accepted' && (currentUserType === 'owner' ? !request.ownerPasswordConfirmed : !request.tenantPasswordConfirmed),
    canSign: request.status === 'accepted' && (currentUserType === 'owner' ? !request.ownerSignature && request.ownerPasswordConfirmed : !request.tenantSignature && request.tenantPasswordConfirmed)
  });

  // Check what step the current user needs to complete
  const needsPasswordConfirmation = currentUserType === 'owner' ? 
    !request.ownerPasswordConfirmed : !request.tenantPasswordConfirmed;

  const needsSignature = currentUserType === 'owner' ?
    !request.ownerSignature && request.ownerPasswordConfirmed :
    !request.tenantSignature && request.tenantPasswordConfirmed;

  const canConfirmPassword = request.status === 'accepted' && needsPasswordConfirmation;
  const canSign = request.status === 'accepted' && needsSignature;

  // Password confirmation mutation
  const confirmPasswordMutation = useMutation({
    mutationFn: async (password: string) => {
      return apiRequest(`/api/contracts/${request.contractId}/confirm-termination-password`, {
        method: 'POST',
        body: JSON.stringify({
          password,
          userType: currentUserType
        })
      });
    },
    onSuccess: () => {
      toast({
        title: "Mot de passe confirmé",
        description: "Vous pouvez maintenant procéder à la signature numérique.",
      });
      setPassword('');
      queryClient.invalidateQueries({ queryKey: [`/api/contract-termination-requests/${request.id}`] });
      queryClient.invalidateQueries({ queryKey: [`/api/contracts/${request.contractId}/termination-request`] });
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Mot de passe incorrect",
        variant: "destructive"
      });
    }
  });

  // Signature submission mutation
  const submitSignatureMutation = useMutation({
    mutationFn: async (signature: string) => {
      return apiRequest(`/api/contracts/${request.contractId}/submit-termination-signature`, {
        method: 'POST',
        body: JSON.stringify({
          signature,
          userType: currentUserType
        })
      });
    },
    onSuccess: () => {
      toast({
        title: "Signature enregistrée",
        description: "Votre signature a été enregistrée avec succès.",
      });
      queryClient.invalidateQueries({ queryKey: [`/api/contract-termination-requests/${request.id}`] });
      queryClient.invalidateQueries({ queryKey: [`/api/contracts/${request.contractId}/termination-request`] });
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Erreur lors de l'enregistrement de la signature",
        variant: "destructive"
      });
    }
  });

  const handlePasswordConfirm = (e: React.FormEvent) => {
    e.preventDefault();
    if (password.trim()) {
      confirmPasswordMutation.mutate(password);
    }
  };

  const handleSignatureSubmit = () => {
    if (signatureRef && !signatureRef.isEmpty()) {
      const signatureData = signatureRef.toDataURL();
      submitSignatureMutation.mutate(signatureData);
    } else {
      toast({
        title: "Signature requise",
        description: "Veuillez signer avant de soumettre.",
        variant: "destructive"
      });
    }
  };

  const clearSignature = () => {
    if (signatureRef) {
      signatureRef.clear();
    }
  };

  return (
    <div className="space-y-6">
      {/* Progress Tracker */}
      <ContractTerminationProgress 
        request={request} 
        currentUserType={currentUserType}
      />

      {/* Password Confirmation Step */}
      {canConfirmPassword && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Lock className="mr-2 h-5 w-5" />
              Confirmation par mot de passe
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="flex items-start space-x-3 p-4 bg-blue-50 border border-blue-200 rounded-lg">
                <AlertCircle className="w-5 h-5 text-blue-600 mt-0.5" />
                <div>
                  <p className="text-sm font-medium text-blue-800">
                    Confirmation de sécurité requise
                  </p>
                  <p className="text-xs text-blue-600 mt-1">
                    Veuillez saisir votre mot de passe pour confirmer votre accord à l'arrêt du contrat.
                  </p>
                </div>
              </div>

              <form onSubmit={handlePasswordConfirm} className="space-y-4">
                <div>
                  <Label htmlFor="password">Mot de passe</Label>
                  <Input
                    id="password"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Saisissez votre mot de passe"
                    required
                    data-testid="input-password-confirm"
                  />
                </div>

                <Button 
                  type="submit" 
                  disabled={confirmPasswordMutation.isPending || !password.trim()}
                  data-testid="button-confirm-password"
                >
                  <Lock className="mr-2 h-4 w-4" />
                  {confirmPasswordMutation.isPending ? 'Vérification...' : 'Confirmer avec mot de passe'}
                </Button>
              </form>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Digital Signature Step */}
      {canSign && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <PenTool className="mr-2 h-5 w-5" />
              Signature numérique
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="flex items-start space-x-3 p-4 bg-green-50 border border-green-200 rounded-lg">
                <CheckCircle className="w-5 h-5 text-green-600 mt-0.5" />
                <div>
                  <p className="text-sm font-medium text-green-800">
                    Prêt pour la signature
                  </p>
                  <p className="text-xs text-green-600 mt-1">
                    Votre mot de passe a été confirmé. Veuillez maintenant signer numériquement pour finaliser l'arrêt du contrat.
                  </p>
                </div>
              </div>

              <div>
                <Label>Votre signature</Label>
                <div className="mt-2 border-2 border-gray-300 rounded-lg">
                  <SignatureCanvas
                    ref={(ref) => setSignatureRef(ref)}
                    canvasProps={{
                      className: 'w-full h-40 rounded-lg',
                      style: { width: '100%', height: '160px' }
                    }}
                    backgroundColor="white"
                    data-testid="signature-canvas"
                  />
                </div>
                <div className="flex justify-between mt-2">
                  <Button 
                    type="button" 
                    variant="outline" 
                    size="sm" 
                    onClick={clearSignature}
                    data-testid="button-clear-signature"
                  >
                    Effacer
                  </Button>
                  <Button 
                    onClick={handleSignatureSubmit}
                    disabled={submitSignatureMutation.isPending}
                    data-testid="button-submit-signature"
                  >
                    <PenTool className="mr-2 h-4 w-4" />
                    {submitSignatureMutation.isPending ? 'Enregistrement...' : 'Enregistrer la signature'}
                  </Button>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Completion Message */}
      {request.status === 'completed' && (
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center space-x-3 text-green-600">
              <CheckCircle className="w-6 h-6" />
              <div>
                <h3 className="font-semibold">Contrat résilié avec succès</h3>
                <p className="text-sm text-gray-600">
                  Toutes les étapes ont été complétées. Le contrat est officiellement résilié.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Waiting for Other Party */}
      {!canConfirmPassword && !canSign && request.status !== 'completed' && (
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center space-x-3 text-blue-600">
              <AlertCircle className="w-6 h-6" />
              <div>
                <h3 className="font-semibold">En attente</h3>
                <p className="text-sm text-gray-600">
                  En attente de l'action de l'autre partie pour continuer le processus d'arrêt.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

