            <Button 
              size="lg" 
              variant="outline" 
              className="hero-button-outline"
              onClick={() => {
                const isAuth = localStorage.getItem("isAuthenticated");
                if (isAuth) {
                  window.location.href = "/add-property";
                } else {
                  window.location.href = "/login";
                }
