import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { CalendarIcon, HandHeart } from "lucide-react";
import { format } from "date-fns";
import { fr } from "date-fns/locale";
import { useToast } from "@/hooks/use-toast";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";

interface Property {
  id: number;
  title: string;
  price: string;
  ownerId: number;
}

interface OfferModalProps {
  property: Property;
  isOpen: boolean;
  onClose: () => void;
}

export default function OfferModal({ property, isOpen, onClose }: OfferModalProps) {
  const [startDate, setStartDate] = useState<Date>();
  const [endDate, setEndDate] = useState<Date>();
  const [monthlyRent, setMonthlyRent] = useState(property.price);
  const [deposit, setDeposit] = useState(property.price);
  const [conditions, setConditions] = useState("");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const offerMutation = useMutation({
    mutationFn: async (offerData: any) => {
      return await apiRequest("/api/offers", {
        method: "POST",
        body: JSON.stringify(offerData),
      });
    },
    onSuccess: () => {
      toast({
        title: "Offre envoyée",
        description: "Votre offre a été transmise au propriétaire",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/offers"] });
      onClose();
      resetForm();
    },
    onError: () => {
      toast({
        title: "Erreur",
        description: "Impossible d'envoyer l'offre",
        variant: "destructive",
      });
    }
  });

  const resetForm = () => {
    setStartDate(undefined);
    setEndDate(undefined);
    setMonthlyRent(property.price);
    setDeposit(property.price);
    setConditions("");
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!startDate || !endDate) {
      toast({
        title: "Dates requises",
        description: "Veuillez sélectionner les dates de début et fin",
        variant: "destructive",
      });
      return;
    }

    // Mock current user - replace with real auth
    const currentUser = JSON.parse(localStorage.getItem("currentUser") || '{"id": 1}');

    const offerData = {
      propertyId: property.id,
      tenantId: currentUser.id,
      ownerId: property.ownerId,
      startDate: startDate.toISOString(),
      endDate: endDate.toISOString(),
      monthlyRent: parseFloat(monthlyRent),
      deposit: parseFloat(deposit),
      conditions: conditions || undefined,
    };

    offerMutation.mutate(offerData);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center space-x-2">
            <HandHeart className="h-5 w-5 text-primary" />
            <span>Faire une offre</span>
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label>Propriété</Label>
            <p className="text-sm text-muted-foreground">{property.title}</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="start-date">Date de début</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className="w-full justify-start text-left font-normal"
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {startDate ? format(startDate, "PPP", { locale: fr }) : "Sélectionner"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={startDate}
                    onSelect={setStartDate}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>

            <div>
              <Label htmlFor="end-date">Date de fin</Label>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className="w-full justify-start text-left font-normal"
                  >
                    <CalendarIcon className="mr-2 h-4 w-4" />
                    {endDate ? format(endDate, "PPP", { locale: fr }) : "Sélectionner"}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0">
                  <Calendar
                    mode="single"
                    selected={endDate}
                    onSelect={setEndDate}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="monthly-rent">Loyer mensuel (€)</Label>
              <Input
                id="monthly-rent"
                type="number"
                value={monthlyRent}
                onChange={(e) => setMonthlyRent(e.target.value)}
                min="0"
                step="10"
                required
              />
            </div>

            <div>
              <Label htmlFor="deposit">Dépôt de garantie (€)</Label>
              <Input
                id="deposit"
                type="number"
                value={deposit}
                onChange={(e) => setDeposit(e.target.value)}
                min="0"
                step="10"
                required
              />
            </div>
          </div>

          <div>
            <Label htmlFor="conditions">Conditions particulières (optionnel)</Label>
            <Textarea
              id="conditions"
              placeholder="Précisez vos conditions ou demandes particulières..."
              value={conditions}
              onChange={(e) => setConditions(e.target.value)}
              rows={3}
            />
          </div>

          <div className="flex justify-end space-x-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>
              Annuler
            </Button>
            <Button type="submit" disabled={offerMutation.isPending}>
              {offerMutation.isPending ? "Envoi..." : "Envoyer l'offre"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/OwnerRequestsDropd.content:
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger, DropdownMenuSeparator, DropdownMenuLabel } from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Bell, Clock, CheckCircle, XCircle, FileText, Search, ArrowRightIcon } from 'lucide-react';
import { useLocation } from 'wouter';

interface OwnerRequestsDropdownProps {
  userId: number;
  userType: string;
}

interface Request {
  id: number;
  status: 'pending' | 'accepted' | 'rejected';
  createdAt: string;
  contractId: number;
  reason?: string;
  terminationType?: string;
  requestedChanges?: string;
}

export function OwnerRequestsDropdown({ userId, userType }: OwnerRequestsDropdownProps) {
  const [, navigate] = useLocation();

  console.log("OwnerRequestsDropdown: userType check:", userType, "userId:", userId);

  // Only show for owners
  if (userType !== 'owner') {
    console.log("OwnerRequestsDropdown: Not showing - userType is not owner");
    return null;
  }

  // Fetch termination requests SENT by this owner
  const { data: sentRequests = [], isLoading: sentLoading, error: sentError } = useQuery<Request[]>({
    queryKey: [`/api/owner-requests/${userId}`],
    queryFn: async () => {
      console.log("OwnerRequestsDropdown: Making API request to", `/api/owner-requests/${userId}`);
      const response = await fetch(`/api/owner-requests/${userId}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        console.error("OwnerRequestsDropdown: API error", response.status, response.statusText);
        throw new Error(`Failed to fetch owner requests: ${response.statusText}`);
      }

      const data = await response.json();
      console.log("OwnerRequestsDropdown: Received data", data);
      return data;
    },
    enabled: userType === 'owner' && !!userId,
    refetchInterval: 5000, // Refetch every 5 seconds for real-time updates
    retry: 3,
    staleTime: 0 // Always fetch fresh data
  });

  // Fetch termination requests RECEIVED by this owner (sent by tenants)
  const { data: receivedRequests = [], isLoading: receivedLoading, error: receivedError } = useQuery<Request[]>({
    queryKey: [`/api/tenant-requests/${userId}`],
    queryFn: async () => {
      const response = await fetch(`/api/tenant-requests/${userId}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch tenant requests: ${response.statusText}`);
      }

      return response.json();
    },
    enabled: userType === 'owner' && !!userId,
    refetchInterval: 5000,
    retry: 3,
    staleTime: 0
  });

  if (sentLoading || receivedLoading || sentError || receivedError) {
    console.log("OwnerRequestsDropdown: Loading or error state", { sentLoading, receivedLoading, sentError, receivedError });
    return (
      <Button 
        variant="outline" 
        size="sm" 
        className="relative"
        data-testid="button-owner-requests-loading"
      >
        <FileText className="h-4 w-4 mr-2" />
        Mes demandes
        {(sentLoading || receivedLoading) && <Badge variant="secondary" className="ml-2">...</Badge>}
      </Button>
    );
  }

  const allRequests = [...sentRequests, ...receivedRequests];
  const pendingRequests = allRequests.filter(req => req.status === 'pending');
  const pendingCount = pendingRequests.length;

  console.log("OwnerRequestsDropdown query result:", { 
    sentRequests,
    receivedRequests,
    allRequests, 
    sentLoading,
    receivedLoading, 
    sentError,
    receivedError,
    queryEnabled: userType === 'owner' && !!userId 
  });

  console.log("OwnerRequestsDropdown: Filtering requests", {
    totalRequests: allRequests.length,
    pendingCount,
    pendingRequests
  });

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'pending':
        return <Clock className="h-4 w-4 text-yellow-500" />;
      case 'accepted':
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      case 'rejected':
        return <XCircle className="h-4 w-4 text-red-500" />;
      default:
        return <FileText className="h-4 w-4 text-gray-500" />;
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'pending':
        return 'En attente de réponse';
      case 'accepted':
        return 'Acceptée';
      case 'rejected':
        return 'Refusée';
      default:
        return status;
    }
  };

  const getTypeText = (type: string) => {
    switch (type) {
      case 'termination':
        return 'Arrêt de contrat';
      case 'modification':
        return 'Modification';
      default:
        return type;
    }
  };

  const determineRequestType = (request: Request): string => {
    // If it has terminationType or reason (termination-specific fields), it's a termination request
    if (request.terminationType || request.reason) {
      return 'termination';
    }
    // If it has requestedChanges, it's a modification request
    if (request.requestedChanges) {
      return 'modification';
    }
    // Default fallback
    return 'termination'; // Most requests in this system are termination requests
  };

  const handleRequestClick = (request: Request, isSent: boolean) => {
    const requestType = determineRequestType(request);
    console.log("OwnerRequestsDropdown: Navigating to request", { requestType, requestId: request.id, request, isSent });
    if (requestType === 'termination') {
      if (isSent) {
        // Request sent by owner - go to workflow to manage it
        navigate(`/owner-termination-workflow/${request.id}`);
      } else {
        // Request received from tenant - go to review to respond
        navigate(`/owner-termination-review/${request.id}`);
      }
    } else {
      navigate(`/owner-request-response/${requestType}/${request.id}`);
    }
  };

  const handleInvestigateRequest = (requestId: number) => {
    navigate(`/contract-termination-status/${requestId}`);
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button 
          variant="outline" 
          size="sm" 
          className="relative"
          data-testid="button-owner-requests"
        >
          <FileText className="h-4 w-4 mr-2" />
          Mes demandes
          {pendingCount > 0 && (
            <Badge variant="destructive" className="ml-2 h-5 w-5 rounded-full p-0 flex items-center justify-center text-xs">
              {pendingCount}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-80">
        <DropdownMenuLabel className="flex items-center">
          <FileText className="h-4 w-4 mr-2" />
          Mes demandes ({allRequests.length})
        </DropdownMenuLabel>
        <DropdownMenuSeparator />

        {/* Demandes envoyées (sent by owner) */}
        {sentRequests.length > 0 && (
          <>
            <DropdownMenuLabel className="flex items-center text-orange-600">
              <ArrowRightIcon className="h-4 w-4 mr-2" />
              Demandes de résiliation envoyées ({sentRequests.length})
            </DropdownMenuLabel>
            {sentRequests.slice(0, 3).map((request) => (
              <DropdownMenuItem 
                key={`sent-${request.id}`}
                className="cursor-pointer"
                data-testid={`menu-item-sent-request-${request.id}`}
              >
                <div className="flex items-start space-x-3 w-full">
                  {getStatusIcon(request.status)}
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-gray-900">
                      Arrêt demandé au locataire
                    </p>
                    <p className="text-sm text-gray-500">
                      {getStatusText(request.status)}
                    </p>
                    <p className="text-xs text-gray-400">
                      Contrat #{request.contractId} • {new Date(request.createdAt).toLocaleDateString('fr-FR')}
                    </p>
                    <div className="flex gap-1 mt-1">
                      <Button 
                        size="sm" 
                        variant="outline" 
                        className="h-6 text-xs"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleRequestClick(request, true);
                        }}
                      >
                        Gérer
                      </Button>
                      <Button 
                        size="sm" 
                        variant="ghost" 
                        className="h-6 text-xs"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleInvestigateRequest(request.id);
                        }}
                      >
                        <Search className="h-3 w-3 mr-1" />
                        État
                      </Button>
                    </div>
                  </div>
                </div>
              </DropdownMenuItem>
            ))}
            <DropdownMenuSeparator />
          </>
        )}

        {/* Demandes reçues (sent by tenants) */}
        {receivedRequests.length > 0 && (
          <>
            <DropdownMenuLabel className="flex items-center text-blue-600">
              <FileText className="h-4 w-4 mr-2" />
              Demandes de résiliation reçues ({receivedRequests.length})
            </DropdownMenuLabel>
            {receivedRequests.slice(0, 3).map((request) => (
              <DropdownMenuItem 
                key={`received-${request.id}`}
                className="cursor-pointer"
                data-testid={`menu-item-received-request-${request.id}`}
              >
                <div className="flex items-start space-x-3 w-full">
                  {getStatusIcon(request.status)}
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-gray-900">
                      {getTypeText(determineRequestType(request))}
                    </p>
                    <p className="text-sm text-gray-500">
                      {getStatusText(request.status)}
                    </p>
                    <p className="text-xs text-gray-400">
                      Contrat #{request.contractId} • {new Date(request.createdAt).toLocaleDateString('fr-FR')}
                    </p>
                    <div className="flex gap-1 mt-1">
                      <Button 
                        size="sm" 
                        variant="outline" 
                        className="h-6 text-xs"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleRequestClick(request, false);
                        }}
                      >
                        Répondre
                      </Button>
                      <Button 
                        size="sm" 
                        variant="ghost" 
                        className="h-6 text-xs"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleInvestigateRequest(request.id);
                        }}
                      >
                        <Search className="h-3 w-3 mr-1" />
                        État
                      </Button>
                    </div>
                  </div>
                </div>
              </DropdownMenuItem>
            ))}
          </>
        )}

        {/* Aucune demande */}
        {sentRequests.length === 0 && receivedRequests.length === 0 && (
          <div className="p-4 text-center text-gray-500">
            <FileText className="h-8 w-8 mx-auto mb-2 opacity-50" />
            <p>Aucune demande de résiliation</p>
          </div>
        )}

        {/* Voir toutes les demandes */}
        {(sentRequests.length > 3 || receivedRequests.length > 3) && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem 
              onClick={() => navigate('/owner-requests')}
              className="text-center cursor-pointer"
              data-testid="menu-item-view-all-owner-requests"
            >
              Voir toutes mes demandes
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

client/src/components/PropertyReviews.ts.content:
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Star, User } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { format } from "date-fns";
import { fr } from "date-fns/locale";

interface PropertyReviewsProps {
  propertyId: number;
}

const PropertyReviews = ({ propertyId }: PropertyReviewsProps) => {
  const [newReview, setNewReview] = useState("");
  const [newRating, setNewRating] = useState(0);
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch reviews from database
  const { data: reviews = [], isLoading } = useQuery({
    queryKey: [`/api/properties/${propertyId}/reviews`],
    queryFn: () => fetch(`/api/properties/${propertyId}/reviews`).then(res => res.json()),
  });

  // Create review mutation
  const createReview = useMutation({
    mutationFn: async (reviewData: any) => {
      return await apiRequest("/api/reviews", {
        method: "POST",
        body: JSON.stringify(reviewData),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [`/api/properties/${propertyId}/reviews`] });
      setNewReview("");
      setNewRating(0);
      toast({
        title: "Avis publié",
        description: "Votre avis a été publié avec succès",
      });
    },
    onError: () => {
      toast({
        title: "Erreur",
        description: "Impossible de publier l'avis",
        variant: "destructive",
      });
    }
  });

  const averageRating = reviews.length > 0 ? reviews.reduce((sum: number, review: any) => sum + review.rating, 0) / reviews.length : 0;

  const handleSubmitReview = () => {
    const isAuth = localStorage.getItem("isAuthenticated");
    if (!isAuth) {
      toast({
        title: "Connexion requise",
        description: "Connectez-vous pour laisser un avis",
        variant: "destructive"
      });
      return;
    }

    if (!newReview.trim() || newRating === 0) {
      toast({
        title: "Informations manquantes",
        description: "Veuillez donner une note et écrire un commentaire",
        variant: "destructive"
      });
      return;
    }

    const currentUser = JSON.parse(localStorage.getItem("user") || '{"id": 1}');
    const reviewData = {
      propertyId: propertyId,
      userId: currentUser.id,
      rating: newRating,
      comment: newReview.trim()
    };

    createReview.mutate(reviewData);
  };

  const renderStars = (rating: number, interactive = false, onRate?: (rating: number) => void) => {
    return (
      <div className="flex space-x-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            className={`h-4 w-4 ${
              star <= rating ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'
            } ${interactive ? 'cursor-pointer hover:fill-yellow-400 hover:text-yellow-400' : ''}`}
            onClick={() => interactive && onRate && onRate(star)}
          />
        ))}
      </div>
    );
  };

  if (isLoading) {
    return (
      <Card className="glass-card">
        <CardContent className="p-6">
          <div className="text-center">
            <div className="animate-spin h-8 w-8 border-4 border-primary border-t-transparent rounded-full mx-auto mb-4"></div>
            <p>Chargement des avis...</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="glass-card">
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <span>Avis et commentaires</span>
          <div className="flex items-center space-x-2">
            {renderStars(Math.round(averageRating))}
            <span className="text-sm text-muted-foreground">
              ({reviews.length} avis)
            </span>
          </div>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Add Review */}
        <div className="glass-card p-4 space-y-4">
          <h4 className="font-medium">Laisser un avis</h4>
          <div>
            <label className="text-sm font-medium mb-2 block">Note</label>
            {renderStars(newRating, true, setNewRating)}
          </div>
          <div>
            <label className="text-sm font-medium mb-2 block">Commentaire (optionnel)</label>
            <Textarea
              value={newReview}
              onChange={(e) => setNewReview(e.target.value)}
              placeholder="Partagez votre expérience avec cette propriété..."
              rows={3}
            />
          </div>
          <Button 
            onClick={handleSubmitReview} 
            className="w-full"
            disabled={createReview.isPending || newRating === 0}
          >
            {createReview.isPending ? "Publication..." : "Publier l'avis"}
          </Button>
        </div>

        {/* Reviews List */}
        <div className="space-y-4">
          {reviews.map((review: any) => (
            <div key={review.id} className="border-b border-border/50 pb-4 last:border-b-0">
              <div className="flex items-start justify-between mb-2">
                <div className="flex items-center space-x-2">
                  <User className="h-4 w-4 text-muted-foreground" />
                  <span className="font-medium text-sm">Utilisateur #{review.userId}</span>
                </div>
                <div className="flex items-center space-x-2">
                  {renderStars(review.rating)}
                  <span className="text-xs text-muted-foreground">
                    {format(new Date(review.createdAt), "dd MMM yyyy", { locale: fr })}
                  </span>
                </div>
              </div>
              {review.comment && (
                <p className="text-sm text-muted-foreground">{review.comment}</p>
              )}
            </div>
          ))}
        </div>

        {reviews.length === 0 && (
          <div className="text-center py-8">
            <p className="text-muted-foreground">Aucun avis pour le moment</p>
            <p className="text-sm text-muted-foreground">Soyez le premier à laisser un avis!</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default PropertyReviews;

