            <Card className="glass-card">
              <CardHeader>
                <CardTitle>Règles du logement</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex space-x-2">
                  <Input
                    value={newRule}
                    onChange={(e) => setNewRule(e.target.value)}
                    placeholder="Ajouter une règle..."
                    onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addRule())}
                  />
                  <Button type="button" onClick={addRule}>
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>

                <div className="space-y-2">
                  {formData.rules.map((rule, index) => (
                    <div key={index} className="flex items-center justify-between p-2 glass-card rounded">
                      <span className="text-sm">{rule}</span>
                      <Button 
                        type="button" 
                        variant="ghost" 
                        size="sm"
                        onClick={() => removeRule(index)}
                      >
                        <X className="h-3 w-3" />
                      </Button>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            {/* Images and Videos */}
            <Card className="glass-card">
              <CardHeader>
                <CardTitle>Photos & Vidéos</CardTitle>
                <p className="text-sm text-muted-foreground">Ajoutez jusqu'à 10 photos/vidéos pour mettre en valeur votre bien</p>
              </CardHeader>
              <CardContent className="space-y-4">
                <div 
                  className="border-2 border-dashed border-gray-300 rounded-xl p-8 hover:border-primary hover:bg-primary/5 transition-all duration-300 group cursor-pointer"
                  onDragOver={(e) => {
                    e.preventDefault();
                    e.currentTarget.classList.add('border-primary', 'bg-primary/10');
                  }}
                  onDragLeave={(e) => {
                    e.preventDefault();
                    e.currentTarget.classList.remove('border-primary', 'bg-primary/10');
                  }}
                  onDrop={(e) => {
                    e.preventDefault();
                    e.currentTarget.classList.remove('border-primary', 'bg-primary/10');
                    const files = Array.from(e.dataTransfer.files);
                    processFiles(files);
                  }}
                  onClick={() => document.getElementById('images')?.click()}
                >
                  <div className="text-center space-y-4">
                    <div className="relative">
                      <div className="p-4 bg-gradient-to-br from-blue-50 to-purple-50 rounded-full w-fit mx-auto group-hover:from-primary/20 group-hover:to-primary/10 transition-colors">
                        <Upload className="h-12 w-12 text-blue-600 group-hover:text-primary transition-colors" />
                      </div>
                      <div className="absolute -top-1 -right-1 p-1 bg-green-500 rounded-full">
                        <span className="text-white text-xs">📸</span>
                      </div>
                    </div>
                    <div>
                      <Label htmlFor="images" className="text-lg font-semibold cursor-pointer hover:text-primary transition-colors">
                        📤 Glissez vos photos ici ou cliquez pour parcourir
                      </Label>
                      <p className="text-sm text-muted-foreground mt-2">
                        🖼️ Images: PNG, JPG, JPEG • 🎬 Vidéos: MP4, MOV
                      </p>
                      <p className="text-xs text-muted-foreground">
                        Maximum 50MB par fichier • Jusqu'à 10 fichiers
                      </p>
                    </div>
                    <div className="flex items-center justify-center space-x-4 text-sm text-muted-foreground">
                      <div className="flex items-center space-x-2">
                        <div className="w-3 h-3 bg-green-500 rounded-full"></div>
                        <span>Glisser-déposer</span>
                      </div>
                      <div className="flex items-center space-x-2">
                        <div className="w-3 h-3 bg-blue-500 rounded-full"></div>
                        <span>Navigation</span>
                      </div>
                    </div>
                    <Input
                      id="images"
                      type="file"
                      multiple
                      accept="image/*,video/*"
                      onChange={handleImageUpload}
                      className="hidden"
                    />
                  </div>
                </div>

                {formData.images.length > 0 && (
                  <div>
                    <h4 className="font-medium mb-4 flex items-center justify-between">
                      <div className="flex items-center">
                        <div className="p-2 bg-green-100 rounded-full mr-3">
                          <Upload className="h-4 w-4 text-green-600" />
                        </div>
                        <span>📸 Photos ajoutées ({formData.images.length}/10)</span>
                      </div>
                      <Badge variant="secondary" className="bg-blue-100 text-blue-700">
                        {formData.images.filter(f => f.type.startsWith('image/')).length} 📷 + {formData.images.filter(f => f.type.startsWith('video/')).length} 🎬
                      </Badge>
                    </h4>
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                      {formData.images.map((file, index) => (
                        <div key={index} className="relative group">
                          <div className="aspect-square rounded-xl overflow-hidden border-2 border-gray-200 hover:border-primary transition-colors shadow-sm bg-white">
                            {file.type.startsWith('image/') ? (
                              <div className="relative w-full h-full">
                                <img
                                  src={URL.createObjectURL(file)}
                                  alt={`Preview ${index + 1}`}
                                  className="w-full h-full object-cover"
                                />
                                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent">
                                  <div className="absolute bottom-2 left-2 right-2">
                                    <div className="flex items-center space-x-1 text-white text-xs">
                                      <span>📷</span>
                                      <span className="font-medium truncate">{file.name}</span>
                                    </div>
                                    <div className="text-white/80 text-xs">
                                      {(file.size / 1024 / 1024).toFixed(1)} MB
                                    </div>
                                  </div>
                                </div>
                              </div>
                            ) : (
                              <div className="w-full h-full bg-gradient-to-br from-purple-100 to-purple-200 flex flex-col items-center justify-center p-4">
                                <div className="text-4xl mb-2">🎬</div>
                                <div className="text-center">
                                  <div className="text-xs font-medium text-purple-800 truncate w-full mb-1">
                                    {file.name}
                                  </div>
                                  <div className="text-xs text-purple-600">
                                    {(file.size / 1024 / 1024).toFixed(1)} MB
                                  </div>
                                </div>
                              </div>
                            )}
                          </div>
                          <Button
                            type="button"
                            variant="destructive"
                            size="icon"
                            className="absolute -top-2 -right-2 h-8 w-8 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-all duration-200 hover:scale-110"
                            onClick={() => removeImage(index)}
                          >
                            <X className="h-4 w-4" />
                          </Button>
                          {/* Primary photo indicator */}
                          {index === 0 && (
                            <div className="absolute top-2 left-2">
                              <Badge className="bg-yellow-500 text-white text-xs px-2 py-1">
                                ⭐ Photo principale
                              </Badge>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                    <div className="mt-4 p-4 bg-blue-50 rounded-xl border border-blue-200">
                      <div className="flex items-start space-x-3">
                        <div className="p-2 bg-blue-100 rounded-full">
                          <div className="text-blue-600 text-sm">💡</div>
                        </div>
                        <div className="text-sm">
                          <p className="font-medium text-blue-800 mb-1">✨ Conseils pour de meilleures photos</p>
                          <ul className="text-blue-600 space-y-1 text-xs">
                            <li>• La première photo sera utilisée comme image principale</li>
                            <li>• Utilisez un bon éclairage naturel</li>
                            <li>• Montrez les différentes pièces et angles</li>
                            <li>• Évitez les photos floues ou sombres</li>
                          </ul>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Pricing */}
            <Card className="glass-card border-2 border-primary/20">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <span className="text-2xl">💰</span>
                  <span>Tarification</span>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="price" className="text-base font-medium">Prix principal *</Label>
                    <div className="relative">
                      <Input
                        id="price"
                        type="number"
                        value={formData.price}
                        onChange={(e) => handleInputChange('price', e.target.value)}
                        placeholder="450"
                        required
                        className="text-lg font-semibold pr-12"
                      />
                      <span className="absolute right-3 top-1/2 transform -translate-y-1/2 text-sm text-muted-foreground">TND</span>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="priceType" className="text-base font-medium">Période</Label>
                    <Select value={formData.priceType} onValueChange={(value) => handleInputChange('priceType', value)}>
                      <SelectTrigger className="text-lg">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="jour">Par jour</SelectItem>
                        <SelectItem value="semaine">Par semaine</SelectItem>
                        <SelectItem value="mois">Par mois</SelectItem>
                        <SelectItem value="année">Par année</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="deposit" className="text-base font-medium flex items-center space-x-2">
                    <span>🛡️</span>
                    <span>Caution (TND)</span>
                  </Label>
                  <Input
                    id="deposit"
                    type="number"
                    value={formData.pricing.deposit}
                    onChange={(e) => handleInputChange('pricing.deposit', e.target.value)}
                    placeholder="200-400"
                    className="text-lg"
                  />
                  <p className="text-xs text-muted-foreground">Montant remboursé en fin de location</p>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center space-x-3">
                    <Checkbox
                      id="utilitiesIncluded"
                      checked={formData.pricing.utilitiesIncluded}
                      onCheckedChange={(checked) => handleInputChange('pricing.utilitiesIncluded', checked)}
                    />
                    <Label htmlFor="utilitiesIncluded" className="text-base font-medium flex items-center space-x-2">
                      <span>⚡</span>
                      <span>Charges incluses dans le prix</span>
                    </Label>
                  </div>

                  <div>
                    <Label htmlFor="utilities" className="text-sm font-medium">Détails des charges</Label>
                    <Input
                      id="utilities"
                      value={formData.pricing.utilities}
                      onChange={(e) => handleInputChange('pricing.utilities', e.target.value)}
                      placeholder="Ex: Électricité incluse jusqu'à 100 TND/mois, eau comprise..."
                      className="mt-1"
                    />
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Availability */}
            <Card className="glass-card">
              <CardHeader>
                <CardTitle>Disponibilité</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <Label htmlFor="availableFrom">Disponible à partir du</Label>
                  <Input
                    id="availableFrom"
                    type="date"
                    value={formData.availability.availableFrom}
                    onChange={(e) => handleInputChange('availability.availableFrom', e.target.value)}
                  />
                </div>

                <div>
                  <Label htmlFor="minimumStay">Séjour minimum</Label>
                  <Select value={formData.availability.minimumStay} onValueChange={(value) => handleInputChange('availability.minimumStay', value)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Sélectionner" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="1 semaine">1 semaine</SelectItem>
                      <SelectItem value="1 mois">1 mois</SelectItem>
                      <SelectItem value="3 mois">3 mois</SelectItem>
                      <SelectItem value="6 mois">6 mois</SelectItem>
                      <SelectItem value="1 an">1 an</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <Label htmlFor="maximumStay">Séjour maximum</Label>
                  <Select value={formData.availability.maximumStay} onValueChange={(value) => handleInputChange('availability.maximumStay', value)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Sélectionner" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="3 mois">3 mois</SelectItem>
                      <SelectItem value="6 mois">6 mois</SelectItem>
                      <SelectItem value="1 an">1 an</SelectItem>
                      <SelectItem value="2 ans">2 ans</SelectItem>
                      <SelectItem value="Illimité">Illimité</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </CardContent>
            </Card>

            {/* Submit */}
            <Card className="glass-card">
              <CardContent className="pt-6">
                <Button type="submit" className="w-full">
                  <Plus className="h-4 w-4 mr-2" />
                  Publier le bien
                </Button>
                <p className="text-xs text-muted-foreground mt-2 text-center">
                  Votre bien sera vérifié avant publication
                </p>
              </CardContent>
            </Card>
          </div>
        </form>
      </div>
    </div>
  );
};

