          <TabsContent value="my-requests" className="space-y-4 mt-6">
            {/* Filters */}
            <Card className="glass-card mb-6">
              <CardContent className="p-4">
                <div className="flex flex-col md:flex-row gap-4">
                  <div className="flex-1">
