  const createOfferMutation = useMutation({
    mutationFn: (data: any) => apiRequest("/api/offers", {
      method: "POST",
      body: JSON.stringify({
        ...data,
        startDate: new Date(data.startDate),
        endDate: new Date(data.endDate),
      }),
