import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import Header from "@/components/Header";
import { LoadingSpinner, PropertySkeleton } from "@/components/LoadingSpinner";
import { NetworkError } from "@/components/ErrorBoundary";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { Checkbox } from "@/components/ui/checkbox";
import { 
  Search as SearchIcon, 
  MapPin, 
  Filter, 
  Heart, 
  Star, 
  Wifi, 
  Car, 
  GraduationCap,
  Users,
  Home,
  Maximize,
  Bed,
  Bath,
  Building,
  TreePine,
  Shield,
  User,
  CheckCircle,
  Waves,
  Wind,
  Utensils,
  Eye
} from "lucide-react";

// FavoriteButton component
const FavoriteButton = ({ propertyId, userId, onFavoriteChange }: { propertyId: number, userId: number | null, onFavoriteChange?: (isFavorited: boolean) => void }) => {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Check if property is favorited
  const { data: isFavorited = false, isLoading } = useQuery({
    queryKey: [`/api/users/${userId}/favorites/${propertyId}/check`],
    queryFn: async () => {
      if (!userId) return false;
      const response = await fetch(`/api/users/${userId}/favorites/${propertyId}/check`);
      if (response.ok) {
        const data = await response.json();
        return data.isFavorited;
      }
      return false;
    },
    enabled: !!userId,
    staleTime: 30000 // 30 seconds
  });

  // Add to favorites mutation
  const addToFavoritesMutation = useMutation({
    mutationFn: async () => {
      if (!userId) throw new Error('User not authenticated');
      return apiRequest(`/api/users/${userId}/favorites`, {
        method: 'POST',
        body: JSON.stringify({ propertyId })
      });
    },
    onSuccess: () => {
      // Invalidate and refetch favorites data
      queryClient.invalidateQueries({ queryKey: [`/api/users/${userId}/favorites`] });
      queryClient.invalidateQueries({ queryKey: [`/api/users/${userId}/favorites/${propertyId}/check`] });

      toast({
        title: "Ajouté aux favoris",
        description: "Le bien a été ajouté à vos favoris"
      });

      onFavoriteChange?.(true);
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible d'ajouter le bien aux favoris",
        variant: "destructive"
      });
    }
  });

  // Remove from favorites mutation
  const removeFromFavoritesMutation = useMutation({
    mutationFn: async () => {
      if (!userId) throw new Error('User not authenticated');
      const response = await fetch(`/api/users/${userId}/favorites/${propertyId}`, {
        method: 'DELETE'
      });
      if (!response.ok) {
        throw new Error('Failed to remove from favorites');
      }
      return response.json();
    },
    onSuccess: () => {
      // Invalidate and refetch favorites data
      queryClient.invalidateQueries({ queryKey: [`/api/users/${userId}/favorites`] });
      queryClient.invalidateQueries({ queryKey: [`/api/users/${userId}/favorites/${propertyId}/check`] });

      toast({
        title: "Retiré des favoris",
        description: "Le bien a été retiré de vos favoris"
      });

      onFavoriteChange?.(false);
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible de retirer le bien des favoris",
        variant: "destructive"
      });
    }
  });

  const handleFavoriteClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!userId) {
      toast({
        title: "Connexion requise",
        description: "Veuillez vous connecter pour ajouter des favoris",
        variant: "destructive"
      });
      return;
    }

    if (isFavorited) {
      removeFromFavoritesMutation.mutate();
    } else {
      addToFavoritesMutation.mutate();
    }
  };

  return (
    <Button 
      variant="ghost" 
      size="icon" 
      className={`absolute top-2 right-2 z-10 backdrop-blur-sm border-0 h-8 w-8 p-0 rounded-full transition-all duration-200 ${
        isFavorited 
          ? 'bg-red-500/80 hover:bg-red-600/80'
          : 'bg-black/20 hover:bg-black/40'
      }`}
      onClick={handleFavoriteClick}
      disabled={isLoading || addToFavoritesMutation.isPending || removeFromFavoritesMutation.isPending}
      data-testid={`button-favorite-${propertyId}`}
    >
      <Heart className={`h-4 w-4 ${isFavorited ? 'text-white fill-white' : 'text-white'}`} />
    </Button>
  );
};

const Search = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [priceRange, setPriceRange] = useState([0, 2000]);
  const [propertyType, setPropertyType] = useState("");
  const [location, setLocation] = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [userLocation, setUserLocation] = useState<GeolocationPosition | null>(null);
  const [categoryFilter, setCategoryFilter] = useState("");
  const [equipmentFilters, setEquipmentFilters] = useState({
    furnished: false,
    unfurnished: false,
    parking: false
  });
  const [, navigate] = useLocation();

  // Get current user ID from localStorage
  const getCurrentUserId = () => {
    try {
      const userData = localStorage.getItem("userData");
      if (userData) {
        const user = JSON.parse(userData);
        return user.id;
      }
    } catch (error) {
      console.error("Error getting user ID:", error);
    }
    return null;
  };

  // Function to track property views
  const trackPropertyView = async (propertyId: number) => {
    try {
      await fetch(`/api/properties/${propertyId}/view`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });
    } catch (error) {
      console.error('Failed to track property view:', error);
    }
  };

  const currentUserId = getCurrentUserId();

  const [properties, setProperties] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);

  useEffect(() => {
    fetchProperties();

    // Handle URL parameters from HeroSection search
    const urlParams = new URLSearchParams(window.location.search);
    const locationParam = urlParams.get('location');
    const maxPriceParam = urlParams.get('maxPrice');
    const userTypeParam = urlParams.get('userType');
    const filterParam = urlParams.get('filter');

    if (locationParam) {
      setSearchQuery(locationParam);
    }
    if (maxPriceParam) {
      const price = parseInt(maxPriceParam);
      setPriceRange([0, price]);
    }
    if (userTypeParam) {
      setCategoryFilter(userTypeParam === 'student' ? 'student' : userTypeParam === 'family' ? 'family' : '');
    }
    if (filterParam) {
      setCategoryFilter(filterParam === 'student' ? 'student' : filterParam === 'family' ? 'family' : '');
    }
  }, []);

  const fetchProperties = async () => {
    try {
      setLoading(true);
      setError(null);

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

      const response = await fetch("/api/properties", {
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`Erreur ${response.status}: ${response.statusText}`);
      }

      const fetchedProperties = await response.json();

      // Fetch owner and review data for each property
      const propertiesWithData = await Promise.all(
        fetchedProperties.map(async (property: any) => {
          // Fetch real owner data
          let ownerName = `Propriétaire ${property.ownerId}`;
          try {
            const ownerResponse = await fetch(`/api/users/${property.ownerId}`);
            if (ownerResponse.ok) {
              const owner = await ownerResponse.json();
              ownerName = owner.firstName ? `${owner.firstName} ${owner.lastName || ''}`.trim() : ownerName;
            }
          } catch (error) {
            console.log('Could not fetch owner data for property', property.id);
          }

          // Fetch real reviews data
          let reviewData = { averageRating: 0, totalReviews: 0 };
          try {
            const reviewsResponse = await fetch(`/api/properties/${property.id}/reviews`);
            if (reviewsResponse.ok) {
              const reviews = await reviewsResponse.json();
              if (reviews.length > 0) {
                reviewData.averageRating = reviews.reduce((sum: number, review: any) => sum + review.rating, 0) / reviews.length;
                reviewData.totalReviews = reviews.length;
              }
            }
          } catch (error) {
            console.log('Could not fetch reviews for property', property.id);
          }

          return {
            ...property,
            location: property.address,
            rating: reviewData.averageRating || 0,
            reviews: reviewData.totalReviews,
            owner: property.owner || ownerName,
            ownerVerified: property.ownerVerified || false,
            ownerRating: property.ownerRating || '0',
            available: property.status === "Disponible",
            isStudentFriendly: property.categories?.includes('Étudiant') || property.type === "studio",
            isFamilyFriendly: property.categories?.includes('Famille') || property.type === "villa" || property.rooms >= 2,
            // Use real views count from backend
            views: property.views || 0,
            // Check if property is new (created within last 7 days)
            isNew: new Date().getTime() - new Date(property.createdAt).getTime() < 7 * 24 * 60 * 60 * 1000,
            // Add category-specific theming data
            themeData: getPropertyTheme(property)
          };
        })
      );

      setProperties(propertiesWithData);
    } catch (error: any) {
      console.error("Error fetching properties:", error);
      setProperties([]);

      if (error.name === 'AbortError') {
        setError("La connexion a pris trop de temps. Vérifiez votre connexion internet.");
      } else if (error.message.includes('Failed to fetch') || error.message.includes('NetworkError')) {
        setError("Impossible de se connecter au serveur. Vérifiez votre connexion internet.");
      } else {
        setError(error.message || "Une erreur s'est produite lors du chargement des propriétés.");
      }
    } finally {
      setLoading(false);
    }
  };

  const retryFetch = () => {
    setRetryCount(prev => prev + 1);
    fetchProperties();
  };

  // Initialize filtered properties with fetched data
  const [filteredProperties, setFilteredProperties] = useState<any[]>([]);

  // Update filtered properties when properties change
  useEffect(() => {
    setFilteredProperties(properties);
  }, [properties]);

  useEffect(() => {
    // Get user location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => setUserLocation(position),
        (error) => console.log("Location access denied")
      );
    }
  }, []);

  const handleLocationSearch = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation(position);
          // Filter properties within 5km radius
          const nearbyProperties = properties.filter(p => 
            calculateDistance(
              position.coords.latitude, 
              position.coords.longitude,
              p.latitude || 34.7404, // Default to Sfax if no coordinates
              p.longitude || 10.7603
            ) <= 5
          );
          setFilteredProperties(nearbyProperties);
        },
        (error) => console.log("Location access denied")
      );
    }
  };

  const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number) => {
    const R = 6371; // Radius of the Earth in km
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
              Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  };

  const handleSearch = () => {
    let filtered = properties;

    // Text search
    if (searchQuery) {
      filtered = filtered.filter(p => 
        p.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.location.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.description?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.address?.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    // Property type filter
    if (propertyType && propertyType !== "all") {
      filtered = filtered.filter(p => p.type === propertyType);
    }

    // Category filter using real database categories
    if (categoryFilter && categoryFilter !== "all") {
      filtered = filtered.filter(p => {
        if (categoryFilter === "student") {
          return p.categories?.includes('Étudiant') || p.isStudentFriendly;
        } else if (categoryFilter === "family") {
          return p.categories?.includes('Famille') || p.isFamilyFriendly;
        } else if (categoryFilter === "summer") {
          return p.categories?.includes('Maison d\'été') || p.type === 'maison_ete';
        } else if (categoryFilter === "vue_mer") {
          return p.categories?.includes('Vue sur mer') || p.amenities?.includes('vue_mer');
        } else if (categoryFilter === "proche_plage") {
          return p.categories?.includes('Proche de la plage');
        }
        return p.categories?.includes(categoryFilter);
      });
    }

    // Price range filter
    filtered = filtered.filter(p => {
      const price = parseFloat(p.price) || 0;
      return price >= priceRange[0] && price <= priceRange[1];
    });

    // Equipment filters
    if (equipmentFilters.furnished && equipmentFilters.unfurnished) {
      // Both selected means show all (no filter)
    } else if (equipmentFilters.furnished) {
      filtered = filtered.filter(p => p.furnished === true);
    } else if (equipmentFilters.unfurnished) {
      filtered = filtered.filter(p => p.furnished === false);
    }

    if (equipmentFilters.parking) {
      filtered = filtered.filter(p => 
        p.amenities?.some((amenity: string) => 
          amenity.toLowerCase().includes('parking') || 
          amenity.toLowerCase().includes('garage')
        )
      );
    }

    setFilteredProperties(filtered);
  };

  const getAmenityIcon = (amenity: string) => {
    const amenityLower = amenity.toLowerCase();
    if (amenityLower.includes('wifi') || amenityLower.includes('internet')) return { icon: <Wifi className="h-3 w-3" />, label: 'Wi-Fi' };
    if (amenityLower.includes('parking') || amenityLower.includes('garage')) return { icon: <Car className="h-3 w-3" />, label: 'Parking' };
    if (amenityLower.includes('climatisation') || amenityLower.includes('clim')) return { icon: <Wind className="h-3 w-3" />, label: 'Climatisation' };
    if (amenityLower.includes('cuisine') || amenityLower.includes('kitchen')) return { icon: <Utensils className="h-3 w-3" />, label: 'Cuisine' };
    if (amenityLower.includes('piscine')) return { icon: <Waves className="h-3 w-3" />, label: 'Piscine' };
    if (amenityLower.includes('jardin')) return { icon: <TreePine className="h-3 w-3" />, label: 'Jardin' };
    if (amenityLower.includes('balcon')) return { icon: <Building className="h-3 w-3" />, label: 'Balcon' };
    return { icon: <Star className="h-3 w-3" />, label: amenity };
  };

  const getPropertyTheme = (property: any) => {
    const type = property.type?.toLowerCase() || '';
    const categories = property.categories || [];

    // Property type themes
    const typeThemes = {
      'studio': { 
        gradient: 'from-purple-500 to-pink-500', 
        bgColor: 'bg-gradient-to-br from-purple-50 to-pink-50',
        icon: '🏠', 
        color: 'text-purple-700',
        badge: 'bg-purple-100 text-purple-700 border-purple-200'
      },
      'appartement': { 
        gradient: 'from-blue-500 to-cyan-500', 
        bgColor: 'bg-gradient-to-br from-blue-50 to-cyan-50',
        icon: '🏢', 
        color: 'text-blue-700',
        badge: 'bg-blue-100 text-blue-700 border-blue-200'
      },
      'villa': { 
        gradient: 'from-green-500 to-emerald-500', 
        bgColor: 'bg-gradient-to-br from-green-50 to-emerald-50',
        icon: '🏡', 
        color: 'text-green-700',
        badge: 'bg-green-100 text-green-700 border-green-200'
      },
      'maison': { 
        gradient: 'from-orange-500 to-red-500', 
        bgColor: 'bg-gradient-to-br from-orange-50 to-red-50',
        icon: '🏘️', 
        color: 'text-orange-700',
        badge: 'bg-orange-100 text-orange-700 border-orange-200'
      },
      'maison_ete': { 
        gradient: 'from-amber-500 via-orange-500 to-pink-500', 
        bgColor: 'bg-gradient-to-br from-amber-50 via-orange-50 to-pink-50',
        icon: '🏖️', 
        color: 'text-amber-700',
        badge: 'bg-gradient-to-r from-amber-100 to-orange-100 text-amber-700 border-amber-200'
      }
    };

    // Category themes with creative icons
    const categoryThemes = {
      'Étudiant': { accent: '🎓', specialBadge: 'Pour étudiants', color: 'text-blue-600', bg: 'bg-blue-50' },
      'Famille': { accent: '👨‍👩‍👧‍👦', specialBadge: 'Pour familles', color: 'text-green-600', bg: 'bg-green-50' },
      'Maison d\'été': { accent: '🏖️', specialBadge: 'Résidence d\'été', color: 'text-amber-600', bg: 'bg-amber-50' },
      'Vue sur mer': { accent: '🌊', specialBadge: 'Vue panoramique', color: 'text-cyan-600', bg: 'bg-cyan-50' },
      'Proche de la plage': { accent: '🏝️', specialBadge: 'Bord de mer', color: 'text-teal-600', bg: 'bg-teal-50' },
      'student': { accent: '🎓', specialBadge: 'Pour étudiants', color: 'text-blue-600', bg: 'bg-blue-50' },
      'family': { accent: '👨‍👩‍👧‍👦', specialBadge: 'Pour familles', color: 'text-green-600', bg: 'bg-green-50' },
      'summer': { accent: '🏖️', specialBadge: 'Résidence d\'été', color: 'text-amber-600', bg: 'bg-amber-50' }
    };

    const baseTheme = typeThemes[type as keyof typeof typeThemes] || typeThemes.appartement;
    const categoryAccents = categories.map((cat: string) => categoryThemes[cat as keyof typeof categoryThemes]).filter(Boolean);

    return {
      ...baseTheme,
      categoryAccents,
      furnished: property.furnished,
      trustScore: getTrustScore(property)
    };
  };

  const getTrustScore = (property: any) => {
    let score = 2; // Base score
    if (property.images && property.images.length > 0) score += 1;
    if (property.reviews > 0) score += 1;
    if (property.ownerVerified) score += 1; // Owner verification adds trust
    if (property.ownerVerificationScore && property.ownerVerificationScore > 70) score += 0.5; // High verification score bonus
    if (property.furnished) score += 0.5;
    if (property.amenities && property.amenities.length > 3) score += 0.5;
    return Math.min(5, score);
  };

  useEffect(() => {
    handleSearch();
  }, [searchQuery, propertyType, categoryFilter, priceRange, equipmentFilters]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white">
      <Header />

      <div className="container mx-auto px-4 py-6 sm:py-8">
        {/* Enhanced Search Header */}
        <div className="text-center mb-6 sm:mb-8">
          <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold bg-gradient-to-r from-primary to-orange-500 bg-clip-text text-transparent mb-4">
            🔍 Trouvez votre logement idéal
          </h1>
          <p className="text-gray-600 text-sm sm:text-base md:text-lg px-4">Découvrez les meilleures propriétés avec des informations détaillées et fiables</p>
        </div>

        {/* Search Bar */}
        <div className="bg-white rounded-2xl shadow-lg p-4 sm:p-6 mb-6 sm:mb-8">
          <div className="flex flex-col sm:flex-col md:flex-row gap-3 sm:gap-4">
            <div className="flex-1">
              <Input
                placeholder="🏠 Rechercher par titre ou adresse..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="border-0 bg-gray-50 text-sm sm:text-base md:text-lg h-10 sm:h-12"
              />
            </div>
            <div className="flex flex-col sm:flex-row gap-2 sm:gap-2">
              <Button 
                onClick={handleLocationSearch}
                variant="outline" 
                className="bg-blue-50 hover:bg-blue-100 text-blue-700 border-blue-200 h-10 sm:h-12 px-4 sm:px-6 text-sm sm:text-base"
              >
                <span className="hidden sm:inline">📍 Près de moi</span>
                <span className="sm:hidden">📍 Localiser</span>
              </Button>
              <Button 
                onClick={() => navigate("/map")}
                variant="default"
                className="bg-primary hover:bg-primary/90 h-10 sm:h-12 px-4 sm:px-6 text-sm sm:text-base"
              >
                <span className="hidden sm:inline">🗺️ Voir la carte</span>
                <span className="sm:hidden">🗺️ Carte</span>
              </Button>
              <Button 
                onClick={() => setShowFilters(!showFilters)}
                variant="outline"
                className="bg-gray-50 hover:bg-gray-100 h-10 sm:h-12 px-4 sm:px-6 text-sm sm:text-base"
              >
                <Filter className="h-4 w-4 mr-2" />
                Filtres
              </Button>
            </div>
          </div>
        </div>

        {/* Enhanced Filters */}
        {showFilters && (
          <Card className="mb-6 sm:mb-8 shadow-lg border-0">
            <CardContent className="p-4 sm:p-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6">
                <div>
                  <label className="text-sm font-semibold mb-3 block text-gray-700">Type de bien</label>
                  <Select value={propertyType} onValueChange={setPropertyType}>
                    <SelectTrigger className="h-11">
                      <SelectValue placeholder="Tous types" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">Tous types</SelectItem>
                      <SelectItem value="studio">🏠 Studio</SelectItem>
                      <SelectItem value="appartement">🏢 Appartement</SelectItem>
                      <SelectItem value="villa">🏡 Villa</SelectItem>
                      <SelectItem value="maison">🏘️ Maison</SelectItem>
                      <SelectItem value="maison_ete">☀️ Maison d'été</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <label className="text-sm font-semibold mb-3 block text-gray-700">Catégorie</label>
                  <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                    <SelectTrigger className="h-11">
                      <SelectValue placeholder="Toutes catégories" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">Toutes catégories</SelectItem>
                      <SelectItem value="student">🎓 Pour étudiants</SelectItem>
                      <SelectItem value="family">👨‍👩‍👧‍👦 Pour familles</SelectItem>
                      <SelectItem value="summer">🏖️ Maison d'été</SelectItem>
                      <SelectItem value="vue_mer">🌊 Vue sur mer</SelectItem>
                      <SelectItem value="proche_plage">🏝️ Proche plage</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <label className="text-sm font-semibold mb-3 block text-gray-700">
                    Budget: {priceRange[0]} - {priceRange[1]} TND
                  </label>
                  <Slider
                    value={priceRange}
                    onValueChange={setPriceRange}
                    max={2000}
                    step={50}
                    className="mt-2"
                  />
                </div>

                <div>
                  <label className="text-sm font-semibold mb-3 block text-gray-700">Équipements</label>
                  <div className="space-y-3">
                    <div className="flex items-center space-x-2">
                      <Checkbox 
                        id="furnished" 
                        checked={equipmentFilters.furnished}
                        onCheckedChange={(checked) => 
                          setEquipmentFilters(prev => ({ ...prev, furnished: checked === true }))
                        }
                      />
                      <label htmlFor="furnished" className="text-sm">🛏️ Meublé</label>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Checkbox 
                        id="unfurnished" 
                        checked={equipmentFilters.unfurnished}
                        onCheckedChange={(checked) => 
                          setEquipmentFilters(prev => ({ ...prev, unfurnished: checked === true }))
                        }
                      />
                      <label htmlFor="unfurnished" className="text-sm">🏠 Non meublé</label>
                    </div>
                    <div className="flex items-center space-x-2">
                      <Checkbox 
                        id="parking" 
                        checked={equipmentFilters.parking}
                        onCheckedChange={(checked) => 
                          setEquipmentFilters(prev => ({ ...prev, parking: checked === true }))
                        }
                      />
                      <label htmlFor="parking" className="text-sm">🚗 Parking</label>
                    </div>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Results */}
        <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4 mb-6 sm:mb-8">
          <h2 className="text-lg sm:text-xl md:text-2xl font-bold text-gray-800">
            🎯 {filteredProperties.length} bien(s) trouvé(s)
          </h2>
          <Select defaultValue="price" onValueChange={(value) => {
            let sorted = [...filteredProperties];
            switch(value) {
              case "price":
                sorted.sort((a, b) => parseFloat(a.price) - parseFloat(b.price));
                break;
              case "price-desc":
                sorted.sort((a, b) => parseFloat(b.price) - parseFloat(a.price));
                break;
              case "rating":
                sorted.sort((a, b) => b.rating - a.rating);
                break;
              case "views":
                sorted.sort((a, b) => b.views - a.views);
                break;
            }
            setFilteredProperties(sorted);
          }}>
            <SelectTrigger className="w-full sm:w-48 h-10 sm:h-11">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="price">💰 Prix croissant</SelectItem>
              <SelectItem value="price-desc">💎 Prix décroissant</SelectItem>
              <SelectItem value="rating">⭐ Mieux notés</SelectItem>
              <SelectItem value="views">👀 Plus vues</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Loading State */}
        {loading && (
          <div className="space-y-8">
            <div className="text-center">
              <LoadingSpinner size="lg" text="Recherche des propriétés..." />
            </div>
            <PropertySkeleton />
          </div>
        )}

        {/* Error State */}
        {error && !loading && (
          <NetworkError 
            message={error}
            onRetry={retryFetch}
          />
        )}

        {/* Enhanced Property Grid */}
        {!loading && !error && (
          <div className="grid grid-cols-1 sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-6 lg:gap-8">
            {filteredProperties.length === 0 ? (
              <div className="col-span-full text-center py-12">
                <div className="mx-auto mb-4 h-16 w-16 rounded-full bg-gray-100 flex items-center justify-center">
                  <Home className="h-8 w-8 text-gray-400" />
                </div>
                <h3 className="text-lg font-semibold mb-2">Aucun bien trouvé</h3>
                <p className="text-muted-foreground">
                  Essayez de modifier vos critères de recherche
                </p>
              </div>
            ) : (
              filteredProperties.map((property) => {
                const theme = property.themeData || getPropertyTheme(property);
                const trustStars = Array.from({ length: 5 }, (_, i) => i < Math.floor(theme.trustScore));

                return (
              <Card 
                key={property.id} 
                className={`cursor-pointer hover:scale-[1.02] hover:shadow-xl transition-all duration-300 border-0 shadow-lg ${theme.bgColor} overflow-hidden`}
                onClick={() => {
                  trackPropertyView(property.id);
                  navigate(`/property/${property.id}`);
                }}
                data-testid={`card-property-${property.id}`}
              >
                <CardContent className="p-0">
                  {/* Enhanced Image Section */}
                  <div className="relative h-48 sm:h-52 overflow-hidden">
                    {property.images && property.images.length > 0 ? (
                      <>
                        <img
                          src={property.images[0]}
                          alt={property.title}
                          className="w-full h-full object-cover transition-transform duration-500 hover:scale-110"
                          data-testid={`img-property-${property.id}`}
                        />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-black/20" />
                        {property.images.length > 1 && (
                          <div className="absolute bottom-2 right-2 bg-black/70 text-white px-2 py-1 rounded-full text-xs font-medium">
                            📷 {property.images.length} photos
                          </div>
                        )}
                      </>
                    ) : (
                      <div className={`h-full bg-gradient-to-br ${theme.gradient} flex items-center justify-center`}>
                        <div className="text-center text-white">
                          <div className="text-4xl mb-2">{theme.icon}</div>
                          <p className="text-sm font-medium">{property.type}</p>
                        </div>
                      </div>
                    )}

                    {/* Enhanced Status and Category Badges */}
                    <div className="absolute top-3 left-3 flex flex-col gap-2">
                      {!property.available && (
                        <Badge className="bg-red-600/90 text-white border-0 backdrop-blur-sm">
                          🚫 Non disponible
                        </Badge>
                      )}
                      {property.available && (
                        <Badge className="bg-green-600/90 text-white border-0 backdrop-blur-sm">
                          ✅ Disponible
                        </Badge>
                      )}
                      {property.furnished && (
                        <Badge className="bg-blue-600/90 text-white border-0 backdrop-blur-sm">
                          🛋️ Meublé
                        </Badge>
                      )}
                    </div>

                    {/* Category Accent Badges */}
                    <div className="absolute top-3 right-3 flex flex-col gap-1">
                      {theme.categoryAccents?.map((accent: any, index: number) => (
                        <Badge key={index} className="bg-white/90 text-gray-800 border-0 backdrop-blur-sm text-xs">
                          {accent.accent} {accent.specialBadge}
                        </Badge>
                      ))}
                    </div>

                    {/* Favorite Button */}
                    <FavoriteButton 
                      propertyId={property.id}
                      userId={currentUserId}
                    />
                  </div>

                  {/* Enhanced Content Section */}
                  <div className="p-4 sm:p-5">
                    {/* Title and Type */}
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xl sm:text-2xl">{theme.icon}</span>
                          <Badge className={`${theme.badge} text-xs`} data-testid={`badge-type-${property.id}`}>
                            {property.type}
                          </Badge>
                        </div>
                        <h3 className="font-bold text-base sm:text-lg leading-tight mb-1 truncate" data-testid={`text-title-${property.id}`}>
                          {property.title}
                        </h3>
                      </div>
                    </div>

                    {/* Price and Details */}
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 sm:gap-0 mb-3">
                      <div className="flex items-baseline gap-1">
                        <span className="text-xl sm:text-2xl font-bold bg-gradient-to-r from-primary to-orange-500 bg-clip-text text-transparent" data-testid={`text-price-${property.id}`}>
                          {property.price}
                        </span>
                        <span className="text-sm text-muted-foreground font-medium">
                          TND/{property.priceType}
                        </span>
                      </div>
                      <div className="flex items-center gap-3 sm:gap-4 text-sm text-muted-foreground">
                        {property.rooms && (
                          <div className="flex items-center gap-1">
                            <Bed className="h-4 w-4" />
                            <span>{property.rooms}</span>
                          </div>
                        )}
                        {property.bathrooms && (
                          <div className="flex items-center gap-1">
                            <Bath className="h-4 w-4" />
                            <span>{property.bathrooms}</span>
                          </div>
                        )}
                        {property.surface && (
                          <div className="flex items-center gap-1">
                            <Home className="h-4 w-4" />
                            <span>{property.surface}m²</span>
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Location with Better Display */}
                    <div className="flex items-center gap-2 mb-3 p-2 bg-white/50 rounded-lg">
                      <MapPin className="h-4 w-4 text-blue-600" />
                      <span className="text-sm font-medium text-gray-700 flex-1" data-testid={`text-location-${property.id}`}>
                        {property.address}
                      </span>
                      {property.geographicHighlight && (
                        <Badge variant="outline" className="text-xs bg-blue-50">
                          📍 {property.geographicHighlight}
                        </Badge>
                      )}
                    </div>

                    {/* Rating, Views and Trust Indicators */}
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                        {/* Real Rating */}
                        {property.rating > 0 ? (
                          <div className="flex items-center gap-1 bg-yellow-50 px-2 py-1 rounded-full" data-testid={`rating-${property.id}`}>
                            <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                            <span className="text-sm font-bold text-yellow-700">
                              {property.rating.toFixed(1)}
                            </span>
                            <span className="text-xs text-yellow-600">
                              ({property.reviews} avis)
                            </span>
                          </div>
                        ) : property.isNew ? (
                          <div className="flex items-center gap-1 bg-green-50 px-2 py-1 rounded-full">
                            <Star className="h-4 w-4 text-green-600" />
                            <span className="text-xs text-green-600 font-medium">Nouveau</span>
                          </div>
                        ) : (
                          <div className="flex items-center gap-1 bg-gray-50 px-2 py-1 rounded-full">
                            <Star className="h-4 w-4 text-gray-400" />
                            <span className="text-xs text-gray-500">Pas d'avis</span>
                          </div>
                        )}

                        {/* Views Counter */}
                        <div className="flex items-center gap-1 bg-blue-50 px-2 py-1 rounded-full" data-testid={`views-${property.id}`}>
                          <Eye className="h-3 w-3 text-blue-600" />
                          <span className="text-xs text-blue-600 font-medium">{property.views} vues</span>
                        </div>
                      </div>

                      {/* Trust Score */}
                      <div className="flex items-center gap-1">
                        <div className="flex">
                          {trustStars.map((filled, i) => (
                            <div key={i} className="relative">
                              <Shield className={`h-3 w-3 ${
                                filled ? 'text-green-500 fill-green-100' : 'text-gray-300'
                              }`} />
                            </div>
                          ))}
                        </div>
                        <span className={`text-xs font-medium ${property.ownerVerified ? 'text-green-600' : 'text-gray-500'}`}>
                          {property.ownerVerified ? 'Vérifié' : 'Non vérifié'}
                        </span>
                      </div>
                    </div>

                    {/* Enhanced Amenities */}
                    {property.amenities && property.amenities.length > 0 && (
                      <div className="mb-4">
                        <div className="flex flex-wrap gap-2">
                          {property.amenities.slice(0, 4).map((amenity: string) => {
                            const amenityInfo = getAmenityIcon(amenity);
                            return (
                              <div key={amenity} className="flex items-center gap-1 bg-white/70 px-2 py-1 rounded-full border">
                                {amenityInfo.icon}
                                <span className="text-xs font-medium">{amenityInfo.label}</span>
                              </div>
                            );
                          })}
                          {property.amenities.length > 4 && (
                            <Badge variant="outline" className="text-xs bg-white/70">
                              +{property.amenities.length - 4} autres
                            </Badge>
                          )}
                        </div>
                      </div>
                    )}

                    {/* Owner Information */}
                    <div className="flex items-center justify-between pt-3 border-t border-white/50">
                      <div className="flex items-center gap-2">
                        <div className="w-6 h-6 bg-gradient-to-br from-gray-400 to-gray-600 rounded-full flex items-center justify-center">
                          <User className="h-3 w-3 text-white" />
                        </div>
                        <span className="text-sm text-gray-600" data-testid={`text-owner-${property.id}`}>{property.owner}</span>
                      </div>
                      <div className={`flex items-center gap-1 text-xs ${property.ownerVerified ? 'text-green-600' : 'text-gray-500'}`}>
                        <CheckCircle className="h-3 w-3" />
                        <span>{property.ownerVerified ? 'Propriétaire vérifié' : 'Non vérifié'}</span>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
                );
              })
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default Search;

client/src/pages/Signup.tsx.content:
import { useState } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { MapPin, GraduationCap, Users, Building, Upload } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useQuery } from "@tanstack/react-query";

const Signup = () => {
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    confirmPassword: "",
    firstName: "",
    lastName: "",
    phone: "",
    userType: "",
    cinNumber: "",
    profilePicture: null as File | null,
    gender: "" as "male" | "female" | "",
    avatarUrl: "",
    acceptTerms: false,
    studentInfo: {
      university: "",
      studentId: ""
    },
    socialAccounts: {
      facebook: "",
      instagram: "",
      linkedin: ""
    }
  });
  const [showAvatarModal, setShowAvatarModal] = useState(false);
  const [selectedGender, setSelectedGender] = useState<"male" | "female" | null>(null);
  const [, navigate] = useLocation();
  const { toast } = useToast();

  const universities = [
    "Université de Tunis El Manar",
    "Université de Sfax", 
    "INSAT",
    "ENSI",
    "IHEC",
    "ESC Tunis",
    "Autre"
  ];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (formData.password !== formData.confirmPassword) {
      toast({
        title: "Erreur",
        description: "Les mots de passe ne correspondent pas.",
        variant: "destructive",
      });
      return;
    }

    if (!formData.acceptTerms) {
      toast({
        title: "Erreur",
        description: "Vous devez accepter les conditions générales d'utilisation.",
        variant: "destructive",
      });
      return;
    }

    // Mock registration
    localStorage.setItem("isAuthenticated", "true");
    localStorage.setItem("userEmail", formData.email);
    localStorage.setItem("userType", formData.userType);
    localStorage.setItem("userProfile", JSON.stringify(formData));

    // Special message for owners
    if (formData.userType === "owner") {
      toast({
        title: "Compte créé - En attente de validation",
        description: "Votre compte propriétaire est en attente de validation par un administrateur. L'activation définitive se fera après paiement.",
      });
    } else {
      toast({
        title: "Inscription réussie!",
        description: "Votre compte a été créé avec succès.",
      });
    }

    navigate("/dashboard");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFormData({ ...formData, profilePicture: file, avatarUrl: "" });
    }
  };

  const handleAvatarSelect = (avatarUrl: string) => {
    setFormData({ ...formData, avatarUrl, profilePicture: null });
    setShowAvatarModal(false);
  };

  // Fetch avatars
  const { data: avatarsData } = useQuery({
    queryKey: ["/api/avatars", selectedGender],
    queryFn: async () => {
      const response = await fetch(`/api/avatars?gender=${selectedGender}`);
      if (!response.ok) throw new Error("Failed to fetch avatars");
      return response.json();
    },
    enabled: showAvatarModal && !!selectedGender
  });

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4">
      <Card className="w-full max-w-2xl glass-card">
        <CardHeader className="text-center">
          <div className="flex items-center justify-center space-x-2 mb-4">
            <div className="gradient-primary p-2 rounded-xl">
              <MapPin className="h-6 w-6 text-white" />
            </div>
            <h1 className="text-2xl font-bold gradient-text">Ekrili</h1>
          </div>
          <CardTitle className="text-2xl">Créer un compte</CardTitle>
          <CardDescription>
            Rejoignez la communauté Ekrili
          </CardDescription>
        </CardHeader>
        <form onSubmit={handleSubmit}>
          <CardContent className="space-y-6">
            {/* Type d'utilisateur */}
            <div className="space-y-3">
              <Label>Je suis...</Label>
              <RadioGroup
                value={formData.userType}
                onValueChange={(value) => setFormData({ ...formData, userType: value })}
                className="grid grid-cols-3 gap-4"
              >
                <div className="flex items-center space-x-2 glass-card p-4 rounded-lg">
                  <RadioGroupItem value="tenant" id="tenant" />
                  <Label htmlFor="tenant" className="flex items-center space-x-2 cursor-pointer">
                    <Users className="h-4 w-4" />
                    <span>Locataire</span>
                  </Label>
                </div>
                <div className="flex items-center space-x-2 glass-card p-4 rounded-lg">
                  <RadioGroupItem value="student" id="student" />
                  <Label htmlFor="student" className="flex items-center space-x-2 cursor-pointer">
                    <GraduationCap className="h-4 w-4" />
                    <span>Étudiant</span>
                  </Label>
                </div>
                <div className="flex items-center space-x-2 glass-card p-4 rounded-lg">
                  <RadioGroupItem value="owner" id="owner" />
                  <Label htmlFor="owner" className="flex items-center space-x-2 cursor-pointer">
                    <Building className="h-4 w-4" />
                    <span>Propriétaire</span>
                  </Label>
                </div>
              </RadioGroup>
            </div>

            {/* Photo et Avatar */}
            <div className="space-y-3">
              <Label>Photo de profil (optionnel)</Label>
              <div className="flex items-center space-x-4">
                <div className="flex-1">
                  <div className="space-y-2">
                    <Label>Genre</Label>
                    <Select value={formData.gender} onValueChange={(value) => setFormData({ ...formData, gender: value as any })}>
                      <SelectTrigger>
                        <SelectValue placeholder="Sélectionner votre genre" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="male">Homme</SelectItem>
                        <SelectItem value="female">Femme</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                <div className="flex space-x-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      setSelectedGender("male");
                      setShowAvatarModal(true);
                    }}
                    disabled={!formData.gender}
                  >
                    👨 Avatar H
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      setSelectedGender("female");
                      setShowAvatarModal(true);
                    }}
                    disabled={!formData.gender}
                  >
                    👩 Avatar F
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => document.getElementById('profile-picture')?.click()}
                  >
                    <Upload className="h-4 w-4" />
                  </Button>
                </div>
              </div>

              {(formData.profilePicture || formData.avatarUrl) && (
                <div className="flex items-center justify-center">
                  <div className="w-20 h-20 rounded-full overflow-hidden border-2 border-border">
                    {formData.avatarUrl ? (
                      <img src={formData.avatarUrl} alt="Avatar sélectionné" className="w-full h-full object-cover" />
                    ) : formData.profilePicture ? (
                      <img src={URL.createObjectURL(formData.profilePicture)} alt="Photo téléchargée" className="w-full h-full object-cover" />
                    ) : null}
                  </div>
                </div>
              )}

              <input
                id="profile-picture"
                type="file"
                accept="image/*"
                onChange={handleFileUpload}
                style={{ display: 'none' }}
              />
            </div>

            {/* Informations personnelles */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="firstName">Prénom</Label>
                <Input
                  id="firstName"
                  value={formData.firstName}
                  onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="lastName">Nom</Label>
                <Input
                  id="lastName"
                  value={formData.lastName}
                  onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="phone">Téléphone *</Label>
              <Input
                id="phone"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                placeholder="+216 XX XXX XXX"
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="cinNumber">3 derniers chiffres de la CIN/Passeport *</Label>
              <Input
                id="cinNumber"
                value={formData.cinNumber}
                onChange={(e) => setFormData({ ...formData, cinNumber: e.target.value })}
                placeholder="123"
                maxLength={3}
                required
              />
            </div>


            {/* Social Accounts */}
            <div className="space-y-4 p-4 glass-card rounded-lg">
              <h3 className="font-semibold">Comptes sociaux (facultatif)</h3>
              <div className="grid grid-cols-1 gap-2">
                <Input
                  placeholder="Profil Facebook"
                  value={formData.socialAccounts.facebook}
                  onChange={(e) => setFormData({ 
                    ...formData, 
                    socialAccounts: { ...formData.socialAccounts, facebook: e.target.value }
                  })}
                />
                <Input
                  placeholder="Profil Instagram"
                  value={formData.socialAccounts.instagram}
                  onChange={(e) => setFormData({ 
                    ...formData, 
                    socialAccounts: { ...formData.socialAccounts, instagram: e.target.value }
                  })}
                />
                <Input
                  placeholder="Profil LinkedIn"
                  value={formData.socialAccounts.linkedin}
                  onChange={(e) => setFormData({ 
                    ...formData, 
                    socialAccounts: { ...formData.socialAccounts, linkedin: e.target.value }
                  })}
                />
              </div>
            </div>

            {/* Informations étudiant */}
            {formData.userType === "student" && (
              <div className="space-y-4 p-4 glass-card rounded-lg">
                <h3 className="font-semibold flex items-center space-x-2">
                  <GraduationCap className="h-4 w-4" />
                  <span>Informations étudiant</span>
                </h3>
                <div className="space-y-2">
                  <Label>Université</Label>
                  <Select
                    value={formData.studentInfo.university}
                    onValueChange={(value) => 
                      setFormData({ 
                        ...formData, 
                        studentInfo: { ...formData.studentInfo, university: value }
                      })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Sélectionnez votre université" />
                    </SelectTrigger>
                    <SelectContent>
                      {universities.map((uni) => (
                        <SelectItem key={uni} value={uni}>{uni}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="studentId">Numéro étudiant</Label>
                  <Input
                    id="studentId"
                    value={formData.studentInfo.studentId}
                    onChange={(e) => 
                      setFormData({ 
                        ...formData, 
                        studentInfo: { ...formData.studentInfo, studentId: e.target.value }
                      })
                    }
                  />
                </div>
              </div>
            )}

            {/* Mots de passe */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="password">Mot de passe</Label>
                <Input
                  id="password"
                  type="password"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  required
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="confirmPassword">Confirmer le mot de passe</Label>
                <Input
                  id="confirmPassword"
                  type="password"
                  value={formData.confirmPassword}
                  onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
                  required
                />
              </div>
            </div>
            {/* Terms and Conditions */}
            <div className="flex items-center space-x-2">
              <Checkbox
                id="acceptTerms"
                checked={formData.acceptTerms}
                onCheckedChange={(checked) => setFormData({ ...formData, acceptTerms: checked as boolean })}
              />
              <Label htmlFor="acceptTerms" className="text-sm cursor-pointer">
                J'accepte les{" "}
                <a href="/terms" className="text-primary hover:underline">conditions générales d'utilisation</a>
                {" "}et la{" "}
                <a href="/privacy" className="text-primary hover:underline">politique de confidentialité</a>
              </Label>
            </div>
          </CardContent>
          <CardFooter className="flex flex-col space-y-4">
            <Button 
              type="submit" 
              className="w-full" 
              disabled={!formData.userType || !formData.acceptTerms}
            >
              Créer mon compte
            </Button>
            <p className="text-sm text-muted-foreground text-center">
              Déjà un compte?{" "}
              <Link to="/login" className="text-primary hover:underline">
                Se connecter
              </Link>
            </p>
          </CardFooter>
        </form>
      </Card>

      {/* Avatar Selection Modal */}
      {showAvatarModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowAvatarModal(false)}>
          <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[80vh] overflow-auto" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-semibold">
                Choisir un avatar {selectedGender === 'male' ? 'masculin' : 'féminin'}
              </h3>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowAvatarModal(false)}
              >
                ✕
              </Button>
            </div>

            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4">
              {avatarsData?.avatars?.map((avatarUrl: string, index: number) => (
                <button
                  key={index}
                  onClick={() => handleAvatarSelect(avatarUrl)}
                  className="relative group rounded-full overflow-hidden hover:ring-4 hover:ring-primary/20 transition-all"
                >
                  <img
                    src={avatarUrl}
                    alt={`Avatar ${index + 1}`}
                    className="w-20 h-20 object-cover rounded-full"
                  />
                  <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors rounded-full" />
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Signup;

client/src/pages/TenantRequestResponse.t.content:
import { useState } from 'react';
import { useParams, useLocation } from 'wouter';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { AlertCircle, CheckCircle, XCircle, Clock, FileText } from 'lucide-react';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';

type RequestType = 'modification' | 'termination';

interface Request {
  id: number;
  contractId: number;
  requestedBy: number;
  status: 'pending' | 'accepted' | 'rejected';
  createdAt: string;
  requestedChanges?: string;
  reason?: string;
  detailedReason?: string;
  terminationType?: string;
  proposedTerms?: {
    timeline?: string;
    financialTerms?: string;
    depositHandling?: string;
    additionalConditions?: string;
  };
  tenantResponse?: string;
  ownerResponse?: string;
}

export default function TenantRequestResponse() {
  const params = useParams();
  const [location, navigate] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [response, setResponse] = useState('');

  // Parse URL to get request type and ID
  // Handle both formats: /tenant-requests/:type/:id and /tenant-request-response/:id
  const requestType = (params.type as RequestType) || 'termination';
  const requestId = parseInt(params.id || '0');

  console.log("TenantRequestResponse: URL params:", { type: params.type, id: params.id });
  console.log("TenantRequestResponse: Parsed values:", { requestType, requestId });

  // Get current user
  const getUserData = () => {
    const userData = localStorage.getItem("userData");
    if (userData) {
      try {
        return JSON.parse(userData);
      } catch (e) {
        console.error("Error parsing userData:", e);
        return null;
      }
    }
    return null;
  };

  const currentUser = getUserData();

  // Fetch request details
  const { data: request, isLoading, error } = useQuery<Request>({
    queryKey: [`/api/contract-termination-requests/${requestId}`],
    enabled: !!requestId && !!currentUser,
    queryFn: async () => {
      console.log("TenantRequestResponse: Making API request to", `/api/contract-termination-requests/${requestId}`);
      const response = await fetch(`/api/contract-termination-requests/${requestId}`);
      if (!response.ok) {
        throw new Error('Failed to fetch request');
      }
      const data = await response.json();
      console.log("TenantRequestResponse: Received request data", data);
      return data;
    }
  });

  console.log("TenantRequestResponse: Query state:", { 
    request, 
    isLoading, 
    error, 
    enabled: !!requestId && !!currentUser,
    queryKey: `/api/contract-termination-requests/${requestId}`
  });

  // Fetch contract details
  const { data: contract } = useQuery<any>({
    queryKey: [`/api/contracts/${request?.contractId}`],
    enabled: !!request?.contractId
  });

  // Response mutation
  const responseMutation = useMutation({
    mutationFn: async (responseType: 'accepted' | 'rejected') => {
      console.log('TenantRequestResponse: Sending response', {
        responseType,
        tenantResponse: response,
        userId: currentUser?.id,
        requestId,
        requestType
      });

      // Use termination requests API
      const apiUrl = `/api/contract-termination-requests/${requestId}/respond`;

      return apiRequest(apiUrl, {
        method: 'PUT',
        body: JSON.stringify({
          response: responseType,
          tenantResponse: response,
          userId: currentUser?.id
        })
      });
    },
    onSuccess: (data, responseType) => {
      toast({
        title: responseType === 'accepted' ? "Demande acceptée" : "Demande refusée",
        description: responseType === 'accepted' 
          ? "Votre acceptation a été envoyée au propriétaire"
          : "Votre refus a été envoyé au propriétaire"
      });

      // Invalidate relevant queries
      queryClient.invalidateQueries({ queryKey: [`/api/contract-termination-requests/${requestId}`] });
      queryClient.invalidateQueries({ queryKey: ['/api/notifications'] });
      queryClient.invalidateQueries({ queryKey: [`/api/tenant-requests`] });
      queryClient.invalidateQueries({ queryKey: [`/api/owner-requests`] });

      // If accepted a termination request, redirect to the termination workflow
      if (responseType === 'accepted' && requestType === 'termination') {
        navigate(`/tenant-termination-workflow/${requestId}`);
      } else {
        // Otherwise navigate back to contracts 
        navigate('/contracts');
      }
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible de traiter votre réponse",
        variant: "destructive"
      });
    }
  });

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-orange-50 to-red-50 p-6">
        <div className="max-w-2xl mx-auto pt-20">
          <div className="text-center">Chargement...</div>
        </div>
      </div>
    );
  }

  if (!request) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-orange-50 to-red-50 p-6">
        <div className="max-w-2xl mx-auto pt-20">
          <Card>
            <CardContent className="text-center p-8">
              <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
              <h2 className="text-xl font-semibold mb-2">Demande non trouvée</h2>
              <p className="text-gray-600">Cette demande n'existe pas ou a été supprimée.</p>
              <Button onClick={() => navigate('/contracts')} className="mt-4">
                Retour aux contrats
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'pending':
        return <Badge variant="outline" className="bg-yellow-50 text-yellow-700 border-yellow-300">
          <Clock className="w-3 h-3 mr-1" /> En attente
        </Badge>;
      case 'accepted':
        return <Badge variant="outline" className="bg-green-50 text-green-700 border-green-300">
          <CheckCircle className="w-3 h-3 mr-1" /> Acceptée
        </Badge>;
      case 'rejected':
        return <Badge variant="outline" className="bg-red-50 text-red-700 border-red-300">
          <XCircle className="w-3 h-3 mr-1" /> Refusée
        </Badge>;
      default:
        return null;
    }
  };

  const isModificationRequest = requestType === 'modification';

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-red-50 p-6">
      <div className="max-w-2xl mx-auto pt-20">
        <Card className="shadow-lg">
          <CardHeader className="text-center pb-6">
            <div className="flex items-center justify-center gap-2 mb-4">
              <FileText className="h-6 w-6 text-orange-600" />
              <CardTitle className="text-2xl text-gray-800">
                {isModificationRequest ? 'Demande de Modification' : 'Demande d\'Arrêt Anticipé'}
              </CardTitle>
            </div>
            {getStatusBadge(request.status)}
          </CardHeader>

          <CardContent className="space-y-6">
            {/* Contract Info */}
            {contract && contract.contractData && (
              <div className="bg-gray-50 p-4 rounded-lg">
                <h3 className="font-semibold text-lg mb-2">Informations du Contrat</h3>
                <p className="text-gray-600">
                  <strong>Propriété:</strong> {contract.contractData.propertyTitle}
                </p>
                <p className="text-gray-600">
                  <strong>Adresse:</strong> {contract.contractData.propertyAddress}
                </p>
                <p className="text-gray-600">
                  <strong>Loyer:</strong> {contract.contractData.monthlyRent} DT/mois
                </p>
              </div>
            )}

            {/* Request Details */}
            <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
              <h3 className="font-semibold text-lg mb-2 text-blue-800">
                Détails de la Demande
              </h3>
              <p className="text-blue-700 mb-2">
                <strong>Date de demande:</strong> {request?.createdAt ? new Date(request.createdAt).toLocaleDateString('fr-FR') : 'N/A'}
              </p>
              {isModificationRequest && request?.requestedChanges && (
                <p className="text-blue-700">
                  <strong>Modifications demandées:</strong> {request.requestedChanges}
                </p>
              )}
              {!isModificationRequest && request?.reason && (
                <div className="space-y-2">
                  <p className="text-blue-700">
                    <strong>Raison:</strong> {request.reason}
                  </p>
                  {request?.detailedReason && (
                    <p className="text-blue-700">
                      <strong>Explication détaillée:</strong> {request.detailedReason}
                    </p>
                  )}
                  {request?.terminationType && (
                    <p className="text-blue-700">
                      <strong>Type d'arrêt:</strong> {
                        request.terminationType === 'mutual' ? 'Arrêt mutuel' :
                        request.terminationType === 'early_by_owner' ? 'Arrêt par le propriétaire' :
                        request.terminationType === 'early_by_tenant' ? 'Arrêt par le locataire' :
                        request.terminationType === 'dispute' ? 'Litige' : 
                        request.terminationType
                      }
                    </p>
                  )}
                </div>
              )}
            </div>

            {/* Proposed Terms Section for Termination Requests */}
            {!isModificationRequest && request?.proposedTerms && (
              <div className="bg-amber-50 p-4 rounded-lg border border-amber-200">
                <h3 className="font-semibold text-lg mb-3 text-amber-800">
                  Conditions Proposées par le Propriétaire
                </h3>
                <div className="space-y-2">
                  {request.proposedTerms.timeline && (
                    <p className="text-amber-700">
                      <strong>Délai souhaité:</strong> {request.proposedTerms.timeline}
                    </p>
                  )}
                  {request.proposedTerms.financialTerms && (
                    <p className="text-amber-700">
                      <strong>Conditions financières:</strong> {request.proposedTerms.financialTerms}
                    </p>
                  )}
                  {request.proposedTerms.depositHandling && (
                    <p className="text-amber-700">
                      <strong>Gestion de la caution:</strong> {request.proposedTerms.depositHandling}
                    </p>
                  )}
                  {request.proposedTerms.additionalConditions && (
                    <p className="text-amber-700">
                      <strong>Conditions supplémentaires:</strong> {request.proposedTerms.additionalConditions}
                    </p>
                  )}
                </div>
              </div>
            )}

            {/* Owner Response Section */}
            {!isModificationRequest && request?.ownerResponse && (
              <div className="bg-purple-50 p-4 rounded-lg border border-purple-200">
                <h3 className="font-semibold text-lg mb-2 text-purple-800">
                  Message du Propriétaire
                </h3>
                <p className="text-purple-700">{request.ownerResponse}</p>
              </div>
            )}

            {/* Response Section */}
            {request?.status === 'pending' ? (
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Votre réponse (optionnelle)
                  </label>
                  <Textarea
                    placeholder="Ajoutez un commentaire..."
                    value={response}
                    onChange={(e) => setResponse(e.target.value)}
                    className="w-full"
                    rows={3}
                  />
                </div>

                <div className="flex gap-4 pt-4">
                  <Button
                    onClick={() => responseMutation.mutate('accepted')}
                    disabled={responseMutation.isPending}
                    className="flex-1 bg-green-600 hover:bg-green-700"
                  >
                    <CheckCircle className="w-4 h-4 mr-2" />
                    Accepter
                  </Button>
                  <Button
                    onClick={() => responseMutation.mutate('rejected')}
                    disabled={responseMutation.isPending}
                    variant="outline"
                    className="flex-1 border-red-300 text-red-700 hover:bg-red-50"
                  >
                    <XCircle className="w-4 h-4 mr-2" />
                    Refuser
                  </Button>
                </div>
              </div>
            ) : (
              <div className="bg-gray-50 p-4 rounded-lg">
                <h3 className="font-semibold mb-2">Réponse donnée</h3>
                <p className="text-gray-600">
                  <strong>Statut:</strong> {request?.status === 'accepted' ? 'Acceptée' : 'Refusée'}
                </p>
                {request?.tenantResponse && (
                  <p className="text-gray-600 mt-2">
                    <strong>Commentaire:</strong> {request.tenantResponse}
                  </p>
                )}
              </div>
            )}

            <div className="pt-4">
              <Button
                onClick={() => navigate('/contracts')}
                variant="outline"
                className="w-full"
              >
                Retour aux contrats
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/pages/TenantTerminationReques.content:
import React, { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useLocation } from 'wouter';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { ArrowLeft, Send, AlertCircle } from 'lucide-react';
import { apiRequest } from '@/lib/queryClient';
import { useToast } from '@/hooks/use-toast';
import Header from '@/components/Header';

interface TenantTerminationRequestProps {
  contractId: number;
  currentUserId: number;
}

export function TenantTerminationRequest({ contractId, currentUserId }: TenantTerminationRequestProps) {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [formData, setFormData] = useState({
    reason: '',
    detailedReason: '',
    terminationType: 'early_by_tenant' as 'mutual' | 'early_by_tenant' | 'dispute',
    proposedTerms: {
      timeline: '',
      rentRefund: '',
      financialTerms: '',
      depositHandling: '',
      additionalConditions: ''
    }
  });

  const createTerminationMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      return apiRequest(`/api/contracts/${contractId}/tenant-termination-request`, {
        method: 'POST',
        body: JSON.stringify({
          requestedBy: currentUserId,
          ...data
        })
      });
    },
    onSuccess: async (response) => {
      toast({
        title: "Demande d'arrêt envoyée",
        description: "Votre demande a été envoyée au propriétaire. Vous recevrez une notification de sa réponse.",
      });
      queryClient.invalidateQueries({ queryKey: [`/api/tenant-requests/${currentUserId}`] });
      queryClient.invalidateQueries({ queryKey: [`/api/contract-termination-requests`] });

      // Redirect to contract termination page with "mes demandes" tab active
      navigate('/contract-termination?tab=my-requests');
    },
    onError: (error: any) => {
      toast({
        title: "Erreur",
        description: error.message || "Impossible d'envoyer la demande",
        variant: "destructive"
      });
    }
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.reason.trim() || !formData.detailedReason.trim()) {
      toast({
        title: "Champs requis",
        description: "Veuillez remplir au minimum la raison et l'explication détaillée",
        variant: "destructive"
      });
      return;
    }
    createTerminationMutation.mutate(formData);
  };

  const updateProposedTerms = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      proposedTerms: {
        ...prev.proposedTerms,
        [field]: value
      }
    }));
  };

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        <div className="flex items-center mb-6">
          <Button
            variant="ghost"
            onClick={() => navigate(`/contract/${contractId}`)}
            className="mr-4"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Retour au contrat
          </Button>
          <h1 className="text-3xl font-bold">Demande d'arrêt de contrat</h1>
        </div>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Send className="mr-2 h-5 w-5" />
              Nouvelle demande d'arrêt
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
              <div className="flex items-start space-x-3">
                <AlertCircle className="w-5 h-5 text-blue-600 mt-0.5" />
                <div>
                  <p className="text-sm font-medium text-blue-800">
                    Information importante
                  </p>
                  <p className="text-xs text-blue-600 mt-1">
                    Cette demande sera envoyée au propriétaire qui devra l'accepter ou la refuser. 
                    Si acceptée, vous devrez tous les deux compléter les étapes de validation : 
                    confirmation par mot de passe et signature numérique.
                  </p>
                </div>
              </div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <Label htmlFor="terminationType">Type de résiliation</Label>
                    <Select
                      value={formData.terminationType}
                      onValueChange={(value: any) => setFormData(prev => ({...prev, terminationType: value}))}
                    >
                      <SelectTrigger data-testid="select-termination-type">
                        <SelectValue placeholder="Choisir le type" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="early_by_tenant">Résiliation anticipée par locataire</SelectItem>
                        <SelectItem value="mutual">Résiliation à l'amiable</SelectItem>
                        <SelectItem value="dispute">Résiliation pour litige</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <Label htmlFor="reason">Raison principale *</Label>
                    <Input
                      id="reason"
                      value={formData.reason}
                      onChange={(e) => setFormData(prev => ({...prev, reason: e.target.value}))}
                      placeholder="Ex: Changement professionnel, déménagement..."
                      required
                      data-testid="input-reason"
                    />
                  </div>

                  <div>
                    <Label htmlFor="detailedReason">Explication détaillée *</Label>
                    <Textarea
                      id="detailedReason"
                      value={formData.detailedReason}
                      onChange={(e) => setFormData(prev => ({...prev, detailedReason: e.target.value}))}
                      placeholder="Expliquez en détail les circonstances et raisons de cette demande..."
                      required
                      rows={4}
                      data-testid="textarea-detailed-reason"
                    />
                  </div>
                </div>

                <div className="space-y-4">
                  <h3 className="font-semibold text-lg">Conditions proposées</h3>

                  <div>
                    <Label htmlFor="timeline">Délai souhaité</Label>
                    <Input
                      id="timeline"
                      value={formData.proposedTerms.timeline}
                      onChange={(e) => updateProposedTerms('timeline', e.target.value)}
                      placeholder="Ex: 30 jours, fin du mois..."
                      data-testid="input-timeline"
                    />
                  </div>

                  <div>
                    <Label htmlFor="financialTerms">Conditions financières</Label>
                    <Input
                      id="financialTerms"
                      value={formData.proposedTerms.financialTerms}
                      onChange={(e) => updateProposedTerms('financialTerms', e.target.value)}
                      placeholder="Pénalités, remboursements..."
                      data-testid="input-financial-terms"
                    />
                  </div>

                  <div>
                    <Label htmlFor="depositHandling">Gestion de la caution</Label>
                    <Input
                      id="depositHandling"
                      value={formData.proposedTerms.depositHandling}
                      onChange={(e) => updateProposedTerms('depositHandling', e.target.value)}
                      placeholder="Remboursement total/partiel..."
                      data-testid="input-deposit-handling"
                    />
                  </div>

                  <div>
                    <Label htmlFor="additionalConditions">Conditions supplémentaires</Label>
                    <Textarea
                      id="additionalConditions"
                      value={formData.proposedTerms.additionalConditions}
                      onChange={(e) => updateProposedTerms('additionalConditions', e.target.value)}
                      placeholder="Autres conditions ou remarques..."
                      rows={3}
                      data-testid="textarea-additional-conditions"
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end space-x-4 pt-6 border-t">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => navigate(`/contract/${contractId}`)}
                  data-testid="button-cancel"
                >
                  Annuler
                </Button>
                <Button
                  type="submit"
                  disabled={createTerminationMutation.isPending}
                  data-testid="button-submit-request"
                >
                  <Send className="mr-2 h-4 w-4" />
                  {createTerminationMutation.isPending ? 'Envoi...' : 'Envoyer la demande'}
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

export default TenantTerminationRequest;

import { useRoute } from 'wouter';
import TenantTerminationRequest from './TenantTerminationRequest';

export function TenantTerminationRequestWrapper() {
  const [match, params] = useRoute("/tenant-termination-request/:contractId");
  const contractId = params?.contractId ? parseInt(params.contractId) : 0;
  const currentUserId = Number(localStorage.getItem("userId")) || 0;

  return (
    <TenantTerminationRequest 
      contractId={contractId} 
      currentUserId={currentUserId} 
    />
  );
}

export default TenantTerminationRequestWrapper;

