import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import Header from "@/components/Header";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { 
  ArrowLeft, 
  MapPin, 
  Star, 
  Home, 
  Bed, 
  Bath, 
  Maximize,
  Wifi,
  Car,
  Shield,
  User,
  CheckCircle,
  Heart,
  Eye
} from "lucide-react";
import { LoadingSpinner } from "@/components/LoadingSpinner";
import { useToast } from "@/hooks/use-toast";

const Compare = () => {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [propertyIds, setPropertyIds] = useState<number[]>([]);

  useEffect(() => {
    // Get property IDs from URL parameters
    const urlParams = new URLSearchParams(window.location.search);
    const propertiesParam = urlParams.get('properties');

    if (propertiesParam) {
      const ids = propertiesParam.split(',').map(id => parseInt(id)).filter(id => !isNaN(id));
      if (ids.length >= 2 && ids.length <= 4) {
        setPropertyIds(ids);
      } else {
        toast({
          title: "Erreur",
          description: "Vous devez sélectionner entre 2 et 4 propriétés à comparer",
          variant: "destructive"
        });
        navigate("/favorites");
      }
    } else {
      toast({
        title: "Aucune propriété sélectionnée",
        description: "Veuillez sélectionner des propriétés depuis vos favoris",
        variant: "destructive"
      });
      navigate("/favorites");
    }
  }, [navigate, toast]);

  // Fetch property details for comparison
  const { data: properties = [], isLoading, error } = useQuery({
    queryKey: ['/api/properties', propertyIds],
    queryFn: async () => {
      if (propertyIds.length === 0) return [];

      const promises = propertyIds.map(async (id) => {
        const response = await fetch(`/api/properties/${id}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch property ${id}`);
        }
        return response.json();
      });

      return Promise.all(promises);
    },
    enabled: propertyIds.length > 0
  });

  const getAmenityIcon = (amenity: string) => {
    if (!amenity || typeof amenity !== 'string') return <CheckCircle className="h-4 w-4" />;

    switch (amenity.toLowerCase()) {
      case "wifi": return <Wifi className="h-4 w-4" />;
      case "parking": return <Car className="h-4 w-4" />;
      case "climatisation": return <Shield className="h-4 w-4" />;
      case "security": return <Shield className="h-4 w-4" />;
      default: return <CheckCircle className="h-4 w-4" />;
    }
  };

  const getPropertyTypeIcon = (type: string) => {
    if (!type || typeof type !== 'string') return "🏠";

    switch (type.toLowerCase()) {
      case "studio": return "🏠";
      case "appartement": return "🏢";
      case "apartment": return "🏢";
      case "villa": return "🏡";
      default: return "🏠";
    }
  };

  const formatPrice = (price: any) => {
    return typeof price === 'string' ? price : `${price}`;
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="container mx-auto px-4 py-8">
          <LoadingSpinner size="lg" text="Chargement de la comparaison..." />
        </div>
      </div>
    );
  }

  if (error || properties.length === 0) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="container mx-auto px-4 py-8">
          <div className="text-center py-16">
            <Home className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
            <h3 className="text-xl font-semibold mb-2">Erreur de chargement</h3>
            <p className="text-muted-foreground mb-6">
              Impossible de charger les propriétés pour la comparaison
            </p>
            <Button onClick={() => navigate("/favorites")} className="flex items-center space-x-2">
              <ArrowLeft className="h-4 w-4" />
              <span>Retour aux favoris</span>
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-3xl font-bold gradient-text flex items-center space-x-3">
              <Eye className="h-8 w-8 text-primary" />
              <span>Comparaison des propriétés</span>
            </h1>
            <p className="text-muted-foreground">
              Comparez {properties.length} propriétés côte à côte
            </p>
          </div>
          <Button 
            onClick={() => navigate("/favorites")} 
            className="flex items-center space-x-2"
          >
            <ArrowLeft className="h-4 w-4" />
            <span>Retour aux favoris</span>
          </Button>
        </div>

        {/* Comparison Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
          {properties.map((property, index) => (
            <Card key={property.id} className="glass-card overflow-hidden">
              <CardHeader className="p-0">
                {/* Property Image */}
                <div className="relative h-48 bg-muted overflow-hidden">
                  {property.images && property.images.length > 0 && property.images[0] !== '/placeholder.svg' ? (
                    <img 
                      src={property.images[0]} 
                      alt={property.title}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <div className="absolute inset-0 flex items-center justify-center">
                      <Home className="h-12 w-12 text-muted-foreground" />
                    </div>
                  )}

                  {/* Property Type Badge */}
                  <Badge className="absolute top-3 left-3 bg-white/90 text-gray-800">
                    {getPropertyTypeIcon(property.type || 'inconnu')} {property.type || 'Type inconnu'}
                  </Badge>
                </div>

                <CardTitle className="p-4 pb-2 text-lg leading-tight">
                  {property.title}
                </CardTitle>
              </CardHeader>

              <CardContent className="p-4 pt-0">
                {/* Price */}
                <div className="mb-4">
                  <div className="text-2xl font-bold bg-gradient-to-r from-primary to-orange-500 bg-clip-text text-transparent">
                    {formatPrice(property.price)} TND/{property.priceType || 'mois'}
                  </div>
                </div>

                {/* Location */}
                <div className="flex items-center gap-2 mb-4 p-2 bg-white/50 rounded-lg">
                  <MapPin className="h-4 w-4 text-blue-600" />
                  <span className="text-sm font-medium text-gray-700 flex-1">
                    {property.address}
                  </span>
                </div>

                {/* Property Details */}
                <div className="grid grid-cols-3 gap-4 mb-4">
                  {property.surface && (
                    <div className="text-center">
                      <div className="flex items-center justify-center mb-1">
                        <Maximize className="h-4 w-4 text-muted-foreground" />
                      </div>
                      <div className="text-sm font-medium">{property.surface}m²</div>
                      <div className="text-xs text-muted-foreground">Surface</div>
                    </div>
                  )}
                  {property.rooms && (
                    <div className="text-center">
                      <div className="flex items-center justify-center mb-1">
                        <Bed className="h-4 w-4 text-muted-foreground" />
                      </div>
                      <div className="text-sm font-medium">{property.rooms}</div>
                      <div className="text-xs text-muted-foreground">Chambres</div>
                    </div>
                  )}
                  {property.bathrooms && (
                    <div className="text-center">
                      <div className="flex items-center justify-center mb-1">
                        <Bath className="h-4 w-4 text-muted-foreground" />
                      </div>
                      <div className="text-sm font-medium">{property.bathrooms}</div>
                      <div className="text-xs text-muted-foreground">S.de bains</div>
                    </div>
                  )}
                </div>

                {/* Rating */}
                {property.rating > 0 ? (
                  <div className="flex items-center gap-2 mb-4 bg-yellow-50 p-2 rounded-lg">
                    <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                    <span className="text-sm font-bold text-yellow-700">
                      {property.rating.toFixed(1)}
                    </span>
                    <span className="text-xs text-yellow-600">
                      ({property.reviews || 0} avis)
                    </span>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 mb-4 bg-gray-50 p-2 rounded-lg">
                    <Star className="h-4 w-4 text-gray-400" />
                    <span className="text-xs text-gray-500">Nouveau bien</span>
                  </div>
                )}

                {/* Amenities */}
                {property.amenities && property.amenities.length > 0 && (
                  <div className="mb-4">
                    <h4 className="text-sm font-semibold mb-2">Équipements</h4>
                    <div className="flex flex-wrap gap-2">
                      {property.amenities.slice(0, 6).map((amenity: string, idx: number) => (
                        <div key={idx} className="flex items-center gap-1 bg-white/70 px-2 py-1 rounded-full border text-xs">
                          {getAmenityIcon(amenity)}
                          <span>{amenity || 'Équipement'}</span>
                        </div>
                      ))}
                      {property.amenities.length > 6 && (
                        <Badge variant="outline" className="text-xs bg-white/70">
                          +{property.amenities.length - 6}
                        </Badge>
                      )}
                    </div>
                  </div>
                )}

                {/* Pricing Details */}
                <div className="mb-4 p-3 bg-gray-50 rounded-lg">
                  <h4 className="text-sm font-semibold mb-2">Tarification</h4>
                  <div className="space-y-1 text-sm">
                    {property.deposit && (
                      <div className="flex justify-between">
                        <span className="text-muted-foreground">Caution:</span>
                        <span className="font-medium">{property.deposit} TND</span>
                      </div>
                    )}
                    {property.fees && (
                      <div className="flex justify-between">
                        <span className="text-muted-foreground">Frais:</span>
                        <span className="font-medium">{property.fees} TND</span>
                      </div>
                    )}
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Charges incluses:</span>
                      <span className="font-medium">{property.utilitiesIncluded ? 'Oui' : 'Non'}</span>
                    </div>
                  </div>
                </div>

                {/* Owner Info */}
                <div className="flex items-center justify-between pt-3 border-t border-gray-200">
                  <div className="flex items-center gap-2">
                    <div className="w-6 h-6 bg-gradient-to-br from-gray-400 to-gray-600 rounded-full flex items-center justify-center">
                      <User className="h-3 w-3 text-white" />
                    </div>
                    <span className="text-sm text-gray-600">{property.owner || 'Propriétaire'}</span>
                  </div>
                  <div className={`flex items-center gap-1 text-xs ${property.ownerVerified ? 'text-green-600' : 'text-gray-500'}`}>
                    <CheckCircle className="h-3 w-3" />
                    <span>{property.ownerVerified ? 'Vérifié' : 'Non vérifié'}</span>
                  </div>
                </div>

                {/* Action Button */}
                <Button 
                  className="w-full mt-4" 
                  onClick={() => navigate(`/property/${property.id}`)}
                >
                  Voir les détails
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Summary Section */}
        <div className="mt-8 p-6 bg-gradient-to-r from-blue-50 to-purple-50 rounded-lg border">
          <h3 className="text-lg font-semibold mb-4">Résumé de la comparaison</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-green-600">
                {Math.min(...properties.map(p => parseFloat(formatPrice(p.price)) || 0))} TND
              </div>
              <div className="text-sm text-muted-foreground">Prix le plus bas</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-600">
                {Math.max(...properties.map(p => p.surface || 0))} m²
              </div>
              <div className="text-sm text-muted-foreground">Plus grande surface</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-orange-600">
                {Math.max(...properties.map(p => p.rating || 0)).toFixed(1)}
              </div>
              <div className="text-sm text-muted-foreground">Meilleure note</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Compare;

client/src/components/UserBadge.tsx.content:
import { Badge } from "@/components/ui/badge";
import { Shield, CheckCircle, Star, Trophy, Clock, MessageSquare } from "lucide-react";

interface UserBadgeProps {
  user: {
    isVerified?: boolean;
    verificationLevel?: string;
    trustScore?: number;
    badges?: any[];
    rating?: string;
    responseRate?: string;
    avgResponseTime?: number;
  };
  showAll?: boolean;
  size?: 'sm' | 'md' | 'lg';
}

export default function UserBadge({ user, showAll = false, size = 'sm' }: UserBadgeProps) {
  const badgeSize = size === 'lg' ? 'h-5 w-5' : size === 'md' ? 'h-4 w-4' : 'h-3 w-3';
  const textSize = size === 'lg' ? 'text-sm' : 'text-xs';

  const getBadges = () => {
    const badges: any[] = [];

    // Verification badge
    if (user.isVerified) {
      badges.push({
        icon: <CheckCircle className={`${badgeSize} text-blue-600`} />,
        label: "Vérifié",
        variant: "default",
        tooltip: "Utilisateur vérifié"
      });
    }

    // Trust level badges
    const trustScore = user.trustScore || 50;
    if (trustScore >= 90) {
      badges.push({
        icon: <Shield className={`${badgeSize} text-gold-600`} />,
        label: "Premium",
        variant: "secondary",
        tooltip: "Utilisateur premium avec un score de confiance élevé"
      });
    } else if (trustScore >= 75) {
      badges.push({
        icon: <Star className={`${badgeSize} text-yellow-600`} />,
        label: "Fiable",
        variant: "outline",
        tooltip: "Utilisateur fiable"
      });
    }

    // Response time badge
    const avgResponseTime = user.avgResponseTime || 24;
    if (avgResponseTime <= 2) {
      badges.push({
        icon: <Clock className={`${badgeSize} text-green-600`} />,
        label: "Réactif",
        variant: "outline",
        tooltip: "Répond rapidement (< 2h)"
      });
    }

    // High rating badge
    const rating = parseFloat(user.rating || "0");
    if (rating >= 4.5) {
      badges.push({
        icon: <Trophy className={`${badgeSize} text-purple-600`} />,
        label: "Top",
        variant: "secondary",
        tooltip: `Note excellente: ${rating}/5`
      });
    }

    // Response rate badge
    const responseRate = parseFloat(user.responseRate || "0");
    if (responseRate >= 90) {
      badges.push({
        icon: <MessageSquare className={`${badgeSize} text-blue-600`} />,
        label: "Communicatif",
        variant: "outline",
        tooltip: `Taux de réponse: ${responseRate}%`
      });
    }

    return badges;
  };

  const badges = getBadges();
  const displayBadges = showAll ? badges : badges.slice(0, 2);

  if (displayBadges.length === 0) {
    return null;
  }

  return (
    <div className="flex items-center space-x-1 flex-wrap">
      {displayBadges.map((badge, index) => (
        <Badge
          key={index}
          variant={badge.variant as any}
          className={`${textSize} flex items-center space-x-1 px-2 py-1`}
          title={badge.tooltip}
        >
          {badge.icon}
          <span>{badge.label}</span>
        </Badge>
      ))}
      {!showAll && badges.length > 2 && (
        <Badge variant="outline" className={`${textSize} px-2 py-1`}>
          +{badges.length - 2}
        </Badge>
      )}
    </div>
  );
}

client/src/components/UserProfile.tsx.content:
import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { LoadingSpinner } from "@/components/LoadingSpinner";
import UserBadge from "./UserBadge";
import { 
  User, 
  MapPin, 
  Calendar, 
  Home, 
  Star, 
  MessageSquare,
  Eye,
  Phone,
  Mail,
  Shield
} from "lucide-react";

interface UserProfileProps {
  userId: number;
  onClose?: () => void;
  showContactInfo?: boolean;
}

export default function UserProfile({ userId, onClose, showContactInfo = false }: UserProfileProps) {
  const [profile, setProfile] = useState<any>(null);
  const [properties, setProperties] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [, navigate] = useLocation();

  useEffect(() => {
    const fetchUserProfile = async () => {
      try {
        setLoading(true);
        setError(null);

        // Fetch public user profile
        const profileResponse = await fetch(`/api/users/${userId}/profile`);
        if (!profileResponse.ok) {
          throw new Error('Failed to fetch user profile');
        }
        const profileData = await profileResponse.json();
        setProfile(profileData);

        // Fetch user's properties if they're an owner
        if (profileData.userType === 'owner') {
          const propertiesResponse = await fetch(`/api/properties?ownerId=${userId}&limit=6`);
          if (propertiesResponse.ok) {
            const propertiesData = await propertiesResponse.json();
            setProperties(propertiesData);
          }
        }
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    if (userId) {
      fetchUserProfile();
    }
  }, [userId]);

  const handleStartConversation = () => {
    navigate(`/messages?newChat=${userId}`);
  };

  if (loading) {
    return (
      <Card className="w-full max-w-2xl mx-auto">
        <CardContent className="p-8 flex items-center justify-center">
          <LoadingSpinner />
        </CardContent>
      </Card>
    );
  }

  if (error || !profile) {
    return (
      <Card className="w-full max-w-2xl mx-auto">
        <CardContent className="p-8 text-center">
          <p className="text-muted-foreground">{error || "Profil utilisateur non trouvé"}</p>
          {onClose && (
            <Button variant="outline" onClick={onClose} className="mt-4">
              Fermer
            </Button>
          )}
        </CardContent>
      </Card>
    );
  }

  const initials = `${profile.firstName?.[0] || ''}${profile.lastName?.[0] || ''}`.toUpperCase() || profile.username?.[0]?.toUpperCase() || 'U';
  const fullName = `${profile.firstName || ''} ${profile.lastName || ''}`.trim() || profile.username;
  const rating = parseFloat(profile.rating || '0');

  return (
    <div className="w-full max-w-4xl mx-auto space-y-6">
      {/* Header */}
      <Card className="glass-card">
        <CardHeader>
          <div className="flex items-start justify-between">
            <div className="flex items-center space-x-4">
              <Avatar className="h-16 w-16">
                <AvatarFallback className="text-lg font-semibold bg-primary text-primary-foreground">
                  {initials}
                </AvatarFallback>
              </Avatar>
              <div>
                <div className="flex items-center space-x-2">
                  <h2 className="text-xl font-bold">{fullName}</h2>
                  {profile.isVerified && (
                    <Shield className="h-5 w-5 text-blue-600" title="Utilisateur vérifié" />
                  )}
                </div>
                <p className="text-muted-foreground capitalize">{profile.userType}</p>
                <UserBadge user={profile} showAll={true} size="md" />
              </div>
            </div>
            {onClose && (
              <Button variant="outline" size="sm" onClick={onClose}>
                ×
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
            {/* Rating */}
            <div className="flex items-center space-x-2">
              <Star className="h-4 w-4 text-yellow-500" />
              <span className="font-medium">{rating.toFixed(1)}</span>
              <span className="text-sm text-muted-foreground">({profile.reviewCount || 0} avis)</span>
            </div>

            {/* Trust Score */}
            <div className="flex items-center space-x-2">
              <Shield className="h-4 w-4 text-blue-500" />
              <span className="font-medium">{profile.trustScore || 50}%</span>
              <span className="text-sm text-muted-foreground">Confiance</span>
            </div>

            {/* Response Rate */}
            {profile.responseRate && (
              <div className="flex items-center space-x-2">
                <MessageSquare className="h-4 w-4 text-green-500" />
                <span className="font-medium">{profile.responseRate}%</span>
                <span className="text-sm text-muted-foreground">Réponses</span>
              </div>
            )}

            {/* Member Since */}
            <div className="flex items-center space-x-2">
              <Calendar className="h-4 w-4 text-gray-500" />
              <span className="text-sm text-muted-foreground">
                Membre depuis {new Date(profile.createdAt).getFullYear()}
              </span>
            </div>
          </div>

          {/* Contact Actions */}
          <div className="flex items-center space-x-4">
            <Button onClick={handleStartConversation} className="flex-1">
              <MessageSquare className="h-4 w-4 mr-2" />
              Contacter
            </Button>

            {showContactInfo && profile.phone && (
              <Button variant="outline" className="flex items-center space-x-2">
                <Phone className="h-4 w-4" />
                <span>{profile.phone}</span>
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Bio Section */}
      {profile.bio && (
        <Card className="glass-card">
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <User className="h-5 w-5" />
              <span>À propos</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-muted-foreground">{profile.bio}</p>
          </CardContent>
        </Card>
      )}

      {/* Properties Section (for owners) */}
      {profile.userType === 'owner' && properties.length > 0 && (
        <Card className="glass-card">
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <Home className="h-5 w-5" />
              <span>Propriétés ({properties.length})</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {properties.map((property) => (
                <div 
                  key={property.id} 
                  className="border rounded-lg p-4 cursor-pointer hover:bg-muted/50 transition-colors"
                  onClick={() => navigate(`/property/${property.id}`)}
                >
                  <div className="aspect-video bg-muted rounded-md mb-3 flex items-center justify-center">
                    <Home className="h-8 w-8 text-muted-foreground" />
                  </div>
                  <h4 className="font-semibold text-sm mb-1">{property.title}</h4>
                  <p className="text-primary font-medium text-sm">{property.price} TND</p>
                  <div className="flex items-center justify-between mt-2 text-xs text-muted-foreground">
                    <div className="flex items-center space-x-1">
                      <MapPin className="h-3 w-3" />
                      <span>{property.address?.split(',')[0]}</span>
                    </div>
                    <div className="flex items-center space-x-1">
                      <Eye className="h-3 w-3" />
                      <span>{property.views || 0}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

client/src/pages/UserProfilePage.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { useParams } from "wouter";
import { ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import Header from "@/components/Header";
import UserProfile from "@/components/UserProfile";

export default function UserProfilePage() {
  const params = useParams<{ userId: string }>();
  const [, navigate] = useLocation();
  const userId = params.userId ? parseInt(params.userId) : null;

  if (!userId) {
    return (
      <div className="min-h-screen bg-background">
        <Header />
        <div className="container mx-auto px-4 py-8">
          <div className="text-center">
            <h1 className="text-2xl font-bold mb-4">Profil utilisateur introuvable</h1>
            <Button onClick={() => navigate("/")} variant="outline">
              Retour à l'accueil
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <div className="container mx-auto px-4 py-8">
        {/* Back Button */}
        <div className="mb-6">
          <Button 
            variant="ghost" 
            onClick={() => navigate(-1)}
            className="flex items-center space-x-2"
          >
            <ArrowLeft className="h-4 w-4" />
            <span>Retour</span>
          </Button>
        </div>

        {/* User Profile */}
        <UserProfile 
          userId={userId} 
          showContactInfo={false}
        />
      </div>
    </div>
  );
}
